window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch14"]={"id": "ch14", "title": "第十四章 新一代测序技术及其应用", "sub": "陈铭《生物信息学》第三版 · 科学出版社", "sub2": "复试生物信息学 · 逐章详解", "modules": [{"i": 0, "name": "第十四章 新一代测序技术及其应用", "slides": [{"i": 0, "sec": "第一节 测序技术概述", "title": "新一代测序技术概述与第一代Sanger测序", "notes": "本章开篇指出，自Sanger测序诞生以来，测序技术经历了多次变革。新一代测序技术包括第二代和第三代测序技术：二代测序以高通量短读长为特征，三代测序注重单分子读取且读长显著提高；但目前二代测序在市场占有率和测序成本方面仍占绝对优势。本章主要介绍二代测序平台、基本原理、应用领域及生物信息学数据处理方法和流程。第一节测序技术概述回顾了测序技术发展：1975年第一个cDNA基因组——噬菌体φX174基因组测序完成，标志测序时代开始。1977年Frederick Sanger提出双脱氧终止法（Sanger测序法），此后鸟枪法和毛细管电泳技术大幅提高测序速度和精度。Sanger测序经过30多年发展，可对长达1000bp的DNA片段测序，单碱基读取准确率高达99.999%，高通量基因组鸟枪法测序费用约0.5美元/1000个碱基。1987年ABI公司推出ABI370。该页为掌握内容，需理解第一代测序原理及其历史地位。", "page": 329, "level": "掌握", "img": "assets/img/ch14/p329.jpg", "anim": null, "fig": null, "points": ["新一代测序技术包括第二代和第三代测序技术", "第二代测序以高通量短读长为特征，第三代测序注重单分子读取且读长显著提高", "目前二代测序在市场占有率和测序成本方面仍占绝对优势", "本章主要介绍二代测序平台、基本原理、应用领域及生物信息学数据处理方法和流程", "1975年第一个测序技术诞生（Sanger测序）", "⚠️ 考点/易错点：易混点：二代测序与三代测序的核心区别（二代=高通量短读长，三代=单分子长读长），且目前二代在市场占有率和成本上仍占绝对优势。"], "code": "", "lang": null, "principle": null, "formula": null, "check": {"q": "根据本章开篇的测序技术发展概述，下列关于测序技术发展历程的说法哪项正确？", "o": ["A. 1975年第一个cDNA基因组——噬菌体φX174基因组测序完成，标志测序时代开始", "B. 第一代测序技术以高通量短读长为特征", "C. 第三代测序技术目前在市场占有率和测序成本方面仍占绝对优势", "D. 第二代测序技术注重单分子读取且读长显著提高"], "a": "A", "e": "本章开篇指出1975年第一个cDNA基因组——噬菌体φX174基因组测序完成，标志测序时代开始。二代测序以高通量短读长为特征，三代测序注重单分子读取且读长显著提高；目前二代测序在市场占有率和测序成本方面仍占绝对优势。"}, "cards": [{"front": "新一代测序技术包括哪两代？各自特点是什么？", "back": "第二代测序以高通量短读长为特征；第三代测序注重单分子读取且读长显著提高。目前二代测序在市场占有率和测序成本方面仍占绝对优势。", "mnemonic": "二代短高通量，三代长单分子", "useImg": false}]}, {"i": 1, "sec": "第一节 测序技术概述", "title": "第二代测序平台概览与第三代测序技术兴起", "notes": "本页介绍第二代测序技术的主要平台。454 Life Sciences公司首先建立高通量第二代测序技术并推出454测序仪（后被Roche收购）；2006年Illumina公司推出Solexa测序仪；2007年ABI推出SOLiD测序仪。这3种平台成为新一代测序主流，具备并行处理大量读长能力，具有高准确性、高通量、高灵敏度和低运行成本等优势。根据平台不同，读取长度为13～450bp；不同平台一次实验可读取高达100Gb碱基数，远超传统测序仪。表14-1列出第二代测序技术平台概览（包括部分三代测序平台），包括454、Solexa、SOLiD、Polonator、HeliScope等，涉及扩增方法、合成方法、每Mb价格、仪器价格、是否能双末端测序、错误产生类型和读长等。例如454采用乳胶PCR和并行焦磷酸合成测序法，读长约250bp，错误类型为Indel；Solexa采用桥式PCR和桥式合成测序法，读长约36bp，错误类型为Subst.；SOLiD采用乳胶PCR和基于磁珠的并行克隆连接DNA测序法，读长约35bp。第三代测序技术也悄然产生，2008年4月Helicos BioSciences公司的Timothy等在Science上报道了单分子测序技术。该页为掌握内容，需熟悉各平台特点及比较。", "page": 330, "level": "掌握", "img": "assets/img/ch14/p330.jpg", "anim": null, "fig": null, "points": ["454 Life Sciences公司首先建立高通量第二代测序技术并推出454测序仪（后被Roche收购）", "2006年Illumina公司推出Solexa测序仪", "2007年ABI推出SOLiD测序仪", "这3种平台成为新一代测序主流，具备并行处理大量读长能力", "具有高准确性、高通量、高灵敏度和低运行成本等优势", "⚠️ 考点/易错点：考点：三大二代测序平台的推出公司与时间——454（Roche收购）、Solexa（Illumina）、SOLiD（ABI），注意读长范围13～450bp及单次实验可达100Gb。"], "code": "", "lang": null, "principle": null, "formula": null, "check": {"q": "关于第二代测序技术的主要平台，下列哪项说法正确？", "o": ["A. Illumina公司首先建立高通量第二代测序技术并推出454测序仪", "B. 454 Life Sciences公司首先建立高通量第二代测序技术并推出454测序仪，后被Roche收购", "C. ABI公司于2006年推出Solexa测序仪", "D. Roche公司于2007年推出SOLiD测序仪"], "a": "B", "e": "454 Life Sciences公司首先建立高通量第二代测序技术并推出454测序仪（后被Roche收购）；2006年Illumina公司推出Solexa测序仪；2007年ABI推出SOLiD测序仪。"}, "cards": [{"front": "第二代测序的三大主流平台是什么？", "back": "454测序仪（Roche收购）、Solexa测序仪（Illumina）、SOLiD测序仪（ABI）。", "mnemonic": "454、Solexa、SOLiD", "useImg": false}]}, {"i": 2, "sec": "第一节 测序技术概述", "title": "Roche 454测序仪原理与流程", "notes": "本页介绍Roche 454测序仪的技术原理和流程。Roche/454 FLX Pyrosequencer主要技术原理是大规模并行焦磷酸合成测序（图14-1）。在DNA聚合酶催化下，dNTP加入DNA的3'端并释放一分子焦磷酸，焦磷酸与腺苷-5'-磷酸硫酸（APS）结合生成ATP，荧光素酶催化氧化荧光素裂解，同时发出荧光，从而进行测定。图中流程包括：(a) DNA文库构建：将基因组DNA随机切割成300～800bp片段，两端加上接头，形成单链DNA文库，约4.5小时；(b) 乳液PCR扩增：单链DNA文库固定在DNA捕获磁珠上，磁珠表面有与文库DNA片段末端互补的寡核苷酸片段，可特异配对连接。乳液PCR利用油水混合物形成油包水稳定乳浊液，将珠子分开，保证每个珠子仅与特定片段连接，珠子内含有PCR反应物。经过约8小时扩增，每个珠子表面可有超过1,000,000个拷贝用于后续测序；(c) 测序：将携带DNA扩增片段的珠子放入PTP（picotiter plate，fused silica capillary structure）板，每个孔只允许结合一个磁珠。将PTP板置于GS FLX中开始测序，每当有核苷酸加到DNA片段上，荧光素酶催化相关反应释放相应强度荧光信号，通过信号转换准确快速获得模板碱基序列，约7.5小时。该页为掌握内容，需理解焦磷酸测序原理及乳液PCR步骤。", "page": 331, "level": "掌握", "img": "assets/img/ch14/p331.jpg", "anim": null, "fig": "图14-1展示Roche 454测序原理与流程。看图时注意从(a)到后续步骤的顺序，理解焦磷酸释放、ATP生成和荧光信号产生的连锁反应。", "points": ["Roche/454 FLX Pyrosequencer主要技术原理是大规模并行焦磷酸合成测序", "在DNA聚合酶催化下，dNTP加入DNA的3'端并释放一分子焦磷酸", "焦磷酸与腺苷-5'-磷酸硫酸（APS）结合生成ATP", "荧光素酶催化氧化荧光素裂解，同时发出荧光，从而进行测定", "图中流程包括：(a) DNA文库制备等步骤", "⚠️ 考点/易错点：核心考点：454测序原理为大规模并行焦磷酸合成测序，关键反应链是dNTP掺入→释放焦磷酸→APS生成ATP→荧光素酶催化发光。"], "code": "# 焦磷酸测序信号模拟（极简）\n# 输入：模板序列 template，待测碱基 flow_order\n# 输出：每个 flow 是否发光及强度\n\ndef pyrosequencing_signal(template, flow_order):\n    signals = []\n    pos = 0\n    for base in flow_order:\n        count = 0\n        while pos < len(template) and template[pos] == base:\n            count += 1\n            pos += 1\n        signals.append((base, count))\n    return signals\n\n# 示例\ntemplate = \"AACGGTT\"\nflow_order = \"ACGT\"\nprint(pyrosequencing_signal(template, flow_order))\n# 输出: [('A', 2), ('C', 1), ('G', 2), ('T', 2)]\n\n# 时间复杂度：O(n + m)，n 为模板长度，m 为 flow 数", "lang": "Python", "principle": "①解决什么问题/用途：Roche 454 测序仪用于对DNA进行大规模并行测序，通过焦磷酸测序法读取模板序列，适用于基因组、PCR产物等样品的快速测序。\n②核心思想（通俗类比）：把DNA合成过程中释放的焦磷酸当作“信号灯”：每掺入一个碱基就释放焦磷酸，经过酶级联反应产生荧光，荧光强弱反映连续掺入相同碱基的个数。类似用“化学放大”把微弱的碱基掺入事件变成可检测的光信号。\n③主要步骤：构建DNA文库（随机切割基因组DNA并加接头）；将单链模板固定在微珠上；进行乳液PCR扩增；将微珠放入PTP板孔中；依次加入四种dNTP，若与模板配对则聚合酶催化掺入并释放焦磷酸；焦磷酸与APS反应生成ATP；荧光素酶催化荧光素氧化发光；检测荧光信号并记录掺入碱基及数量。\n④复杂度或关键参数：读长约400-500 bp，通量较高但低于后续平台；关键参数包括dNTP加入顺序、信号强度与同聚物长度关系。\n⑤优缺点/适用场景：优点是读长较长、无需荧光标记dNTP、可检测同聚物；缺点是对同聚物长度判断易出错（如连续多个相同碱基信号强度非线性），试剂成本较高。适用于需要较长读长的基因组测序和宏基因组研究。", "formula": [{"name": "焦磷酸测序发光反应", "expr": "dNTP + DNA(n) → DNA(n+1) + PPi；PPi + APS → ATP + SO4；ATP + 荧光素 → 氧化荧光素 + 光", "note": "DNA聚合酶催化dNTP延伸释放焦磷酸PPi；ATP硫酸化酶催化PPi与APS生成ATP；荧光素酶催化发光", "tex": "\\mathrm{dNTP} + \\mathrm{DNA}(n) \\rightarrow \\mathrm{DNA}(n+1) + \\mathrm{PPi};\\quad \\mathrm{PPi} + \\mathrm{APS} \\rightarrow \\mathrm{ATP} + \\mathrm{SO_4};\\quad \\mathrm{ATP} + \\text{荧光素} \\rightarrow \\text{氧化荧光素} + \\text{光}"}], "check": {"q": "Roche 454测序仪的主要技术原理是什么？", "o": ["A. 大规模并行连接测序", "B. 大规模并行焦磷酸合成测序", "C. 桥式PCR合成测序", "D. 单分子荧光合成测序"], "a": "B", "e": "Roche/454 FLX Pyrosequencer主要技术原理是大规模并行焦磷酸合成测序。在DNA聚合酶催化下，dNTP加入DNA的3'端并释放焦磷酸，焦磷酸与APS结合生成ATP，荧光素酶催化氧化荧光素裂解并发出荧光，从而进行测定。"}, "cards": [{"front": "Roche 454测序仪的主要技术原理是什么？", "back": "大规模并行焦磷酸合成测序。在DNA聚合酶催化下，dNTP加入DNA的3'端并释放焦磷酸，焦磷酸与APS结合生成ATP，荧光素酶催化氧化荧光素裂解，同时发出荧光，从而进行测定。", "mnemonic": "焦磷酸→ATP→荧光", "useImg": false}]}, {"i": 3, "sec": "第一节 测序技术概述", "title": "454测序文库制备、乳液PCR与测序步骤", "notes": "本页详细说明454测序的三个主要步骤。1) 文库制备：随机切割样品基因组获得大量DNA片段。GS FLX系统支持各种来源样品，包括基因组DNA、PCR产物、BAC、cDNA、小分子RNA等。大样品如基因组DNA或BAC被打断成300～800bp片段；小分子非编码RNA或PCR扩增产物则不需要打断。然后在3'端和5'端接上接头进行扩增反应，具有接头的单链DNA片段组成样品文库（图14-1a）。2) 乳液PCR扩增：单链DNA文库固定在特别设计的DNA捕获磁珠上。磁珠表面有很多可与文库中DNA片段末端互补的寡核苷酸片段，因此可与特异DNA片段配对连接。乳液PCR利用油水混合物形成油包水稳定乳浊液，将珠子分开，保证每个珠子仅与特定片段连接，珠子内同样含有PCR所需反应物。经过一小时扩增后，每个珠子表面可有多余1,000,000个拷贝用于后续测序（图14-1b）。3) 测序：将携带DNA扩增片段的珠子放入PTP（picotiter plate）板上，由于PTP孔直径较小，每个孔只允许结合一个磁珠。将PTP板置于GS FLX中开始测序。每当有核苷酸加到DNA片段上，荧光素酶催化相关反应释放相应强度荧光信号，通过信号转换后准确快速获得模板碱基序列（图14-1c）。尽管GS FLX测序系统准确率较高，一般在99%以上，但该方法也有不足之处：如果被测序片段中含有几个连续相同碱基，测序时会连续发出同样光信号，由于没有终止元件来终止反应，信号会不断发出，导致同聚物错误。该页为掌握内容，需理解各步骤细节及局限性。", "page": 332, "level": "掌握", "img": "assets/img/ch14/p332.jpg", "anim": null, "fig": null, "points": ["454测序的三个主要步骤：文库制备、乳液PCR、测序", "文库制备：随机切割样品基因组获得大量DNA片段", "GS FLX系统支持各种来源样品，包括基因组DNA、PCR产物、BAC、cDNA、小分子RNA等", "大样品如基因组DNA或BAC被打断成300～800bp片段；小分子非编码RNA或PCR扩增产物则不需要打断", "在3'端和5'端接上接头进行扩增反应", "⚠️ 考点/易错点：易错点：454文库制备中，基因组DNA/BAC需打断成300～800bp，而小分子RNA或PCR产物不需打断；三大步骤为文库制备、乳液PCR、测序。"], "code": "# 454 乳液 PCR 微珠分配模拟（极简）\n# 目标：将 DNA 片段分配到大量油包水微滴中，使多数微滴含 0 或 1 个模板\n\nimport random\n\ndef emulsion_pcr_simulation(n_fragments, n_droplets):\n    droplets = [0] * n_droplets\n    for _ in range(n_fragments):\n        droplets[random.randrange(n_droplets)] += 1\n    return droplets\n\n# 示例：1000 个片段分配到 100000 个微滴\nd = emulsion_pcr_simulation(1000, 100000)\nprint(\"空微滴比例:\", d.count(0) / len(d))\nprint(\"单模板微滴比例:\", d.count(1) / len(d))\n\n# 时间复杂度：O(n_fragments)", "lang": "Python", "principle": "①解决什么问题/用途：本页说明454测序中文库制备、乳液PCR和测序步骤，解决如何将复杂基因组样品转化为可测序的微珠模板并实现大规模并行扩增的问题。\n②核心思想（通俗类比）：乳液PCR像“把每个DNA片段关进独立的小房间（油包水微滴）”，每个房间只容纳一个模板和一个微珠，从而在各自房间内单独扩增，避免不同片段混合。\n③主要步骤：1) 文库制备：将基因组DNA随机打断成300-800 bp片段，末端修复并连接接头；小RNA或PCR产物可直接加接头。2) 乳液PCR：将单链DNA片段与微珠混合，在油包水微滴中每个微滴含0或1个模板，进行PCR扩增，使微珠表面富集大量相同拷贝。3) 测序：将微珠放入PTP板，依次加入dNTP进行焦磷酸测序，检测荧光信号。\n④复杂度或关键参数：微滴数量与片段数量比例影响单克隆性；理想情况多数微滴含0或1个模板，需控制浓度。复杂度主要取决于PCR扩增和信号采集。\n⑤优缺点/适用场景：优点是能实现单分子级扩增和并行测序；缺点是乳液PCR操作复杂、微滴稳定性要求高。适用于基因组、BAC、cDNA和小RNA等样品的测序。", "formula": [], "check": {"q": "关于454测序的文库制备，下列哪项说法正确？", "o": ["A. 所有样品都必须打断成300～800bp片段", "B. 小分子非编码RNA或PCR扩增产物也需要打断", "C. 大样品如基因组DNA或BAC被打断成300～800bp片段，小分子非编码RNA或PCR扩增产物则不需要打断", "D. 文库制备后直接进行测序，无需乳液PCR扩增"], "a": "C", "e": "454测序文库制备中，大样品如基因组DNA或BAC被打断成300～800bp片段；小分子非编码RNA或PCR扩增产物则不需要打断。然后在3'端和5'端接上接头进行扩增反应，具有接头的单链DNA片段组成样品文库。"}, "cards": [{"front": "454测序的三个主要步骤是什么？", "back": "1) 文库制备：随机切割样品基因组获得大量DNA片段，接上接头；2) 乳液PCR；3) 测序。", "mnemonic": "文库、乳液PCR、测序", "useImg": false}]}, {"i": 4, "sec": "第一节 测序技术概述", "title": "Illumina/Solexa测序原理与流程", "notes": "本页介绍Illumina/Solexa测序原理（图14-2）。流程包括：(a) 文库制备与桥式PCR：将样本基因组DNA随机打断并接上接头，单链DNA片段与玻璃板上的引物杂交结合；双链解链后，另一端与平板上引物结合形成桥式连接，并进行扩增。经过多轮扩增，在测序flow cell中形成密集的簇。(b) 测序：在测序flow cell中加入4种荧光标记的dNTP、DNA聚合酶及接头引物，每加入一个标记的dNTP就能释放出相应的荧光，测序仪捕获荧光信号，并通过计算机软件将光信号转化为测序峰，从而获得待测片段的序列信息。从荧光信号获取待测片段序列信息的过程叫做Base Calling。经过足够的反应循环后，得到database profile。Illumina公司Base Calling所用的软件是Illumina's Genome Analyzer Sequencing Control Software and Pipeline Analysis Software。该页为掌握内容，需理解桥式PCR和可逆终止子测序原理。", "page": 333, "level": "掌握", "img": "assets/img/ch14/p333.jpg", "anim": null, "fig": "图14-2展示Illumina/Solexa测序原理。看图时注意桥式PCR的形成过程和测序时荧光标记dNTP的加入与读取。", "points": ["Illumina/Solexa测序流程包括：(a) 文库制备与桥式PCR；(b) 测序", "文库制备与桥式PCR：将样本基因组DNA随机打断并接上接头，单链DNA片段与玻璃板上的引物杂交结合", "双链解链后，另一端与平板上引物结合形成桥式连接，并进行扩增", "经过多轮扩增，在测序flow cell中形成密集的簇", "测序：在测序flow cell中加入4种荧光标记的dNTP", "⚠️ 考点/易错点：考点：Illumina/Solexa的核心是桥式PCR在flow cell上形成簇，以及边合成边测序（荧光标记dNTP+DNA聚合酶）。"], "code": "# Illumina 桥式 PCR 簇生成与边合成边测序模拟（极简）\n# 输入：单链 DNA 片段序列\n# 输出：每轮加入荧光 dNTP 后读取的碱基\n\ndef illumina_sequencing(read, cycles):\n    result = []\n    for i in range(min(cycles, len(read))):\n        base = read[i]\n        # 模拟荧光标记 dNTP 掺入并成像\n        result.append(base)\n    return \"\".join(result)\n\n# 示例\nread = \"ACGTACGT\"\nprint(illumina_sequencing(read, 8))\n# 输出: ACGTACGT\n\n# 时间复杂度：O(cycles)", "lang": "Python", "principle": "①解决什么问题/用途：Illumina/Solexa测序用于高通量、短读长的大规模并行DNA测序，广泛应用于基因组重测序、转录组测序和表观遗传研究。\n②核心思想（通俗类比）：桥式PCR像“在玻璃板上种树”：单链DNA片段两端分别与板上引物结合，形成拱桥状，反复扩增后在原位形成密集的克隆簇；测序时每轮只加一个带荧光标记的dNTP，拍照识别碱基，再切掉荧光基团继续下一轮。\n③主要步骤：1) 文库制备：基因组DNA随机打断并加接头。2) 桥式PCR：单链片段与flow cell上引物杂交，延伸后解链，另一端与邻近引物结合形成桥，扩增形成簇。3) 测序：加入四种荧光标记dNTP和聚合酶，每轮只掺入一个碱基，洗去未掺入的dNTP，拍照记录荧光颜色，切除荧光基团和阻断基团，进入下一轮。\n④复杂度或关键参数：读长通常50-300 bp，通量极高；关键参数包括簇密度、荧光信号分辨率和循环数。\n⑤优缺点/适用场景：优点是通量高、成本低、准确度高；缺点是读长较短，对重复序列和结构变异解析有限。适用于全基因组重测序、RNA-seq、ChIP-seq等。", "formula": [], "check": {"q": "Illumina/Solexa测序流程中，在测序flow cell中形成密集的簇是通过什么方式实现的？", "o": ["A. 乳液PCR", "B. 桥式PCR", "C. 连接酶反应", "D. 焦磷酸测序"], "a": "B", "e": "Illumina/Solexa测序流程中，单链DNA片段与玻璃板上的引物杂交结合，双链解链后另一端与平板上引物结合形成桥式连接并进行扩增，经过多轮扩增，在测序flow cell中形成密集的簇。"}, "cards": [{"front": "Illumina/Solexa测序流程包括哪两个主要步骤？", "back": "(a) 文库制备与桥式PCR：DNA片段与玻璃板上的引物杂交结合，形成桥式连接并扩增，形成密集的簇；(b) 测序：加入4种荧光标记的dNTP进行测序。", "mnemonic": "桥式PCR，荧光测序", "useImg": false}]}, {"i": 5, "sec": "第一节 测序技术概述", "title": "SOLiD测序原理与流程", "notes": "本页介绍SOLiD测序仪的原理和流程。1) 文库制备：SOLiD测序仪支持两种测序文库：片段文库（fragment library）或配对末端文库（mate-paired library）。片段文库就是将基因组DNA打断，两头加上接头，制成文库。配对末端文库是将基因组DNA打断后，与中间接头连接，再环化，然后用EcoP15酶切，使中间接头两端各有25～27bp的碱基，再加上两端的接头，形成文库。2) 微乳液PCR扩增：在微反应器中加入测序模板、PCR反应元件、微珠和引物，进行乳液PCR（emulsion PCR）。PCR扩增反应结束后，变性模板，富集带有延伸模板的微珠，去除多余的微珠。微珠上的模板经过3'修饰，可以与玻片共价结合，从而制成高密度测序芯片。3) SOLiD测序反应：采用双碱基探针，探针上有第1位和第2位碱基标记荧光，通过连接反应确定序列。图中显示SOLiD反应底物、模板、玻璃平板、剪切位点、启动并连接、重复1～4延长合成链、链接循环、Universal seq primer等步骤。SOLiD测序通过多次连接循环和引物重置，最终获得序列信息。该页为掌握内容，需理解SOLiD连接测序原理及双碱基编码特点。", "page": 334, "level": "掌握", "img": "assets/img/ch14/p334.jpg", "anim": null, "fig": null, "points": ["SOLiD测序仪支持两种测序文库：片段文库或配对末端文库", "片段文库就是将基因组DNA打断，两头加上接头，制成文库", "配对末端文库是将基因组DNA打断后，与中间接头连接，再环化，然后用EcoP15酶切", "使中间接头两端各有25～27bp的片段", "⚠️ 考点/易错点：易混点：SOLiD两种文库——片段文库与配对末端文库的构建差异，配对末端文库需中间接头连接、环化及EcoP15酶切。"], "code": "# SOLiD 双碱基编码模拟（极简）\n# SOLiD 通过连接测序读取双碱基编码，再解码为碱基序列\n\n# 双碱基编码表（简化）\nencoding = {\n    \"AA\": \"0\", \"CC\": \"0\", \"GG\": \"0\", \"TT\": \"0\",\n    \"AC\": \"1\", \"CA\": \"1\", \"GT\": \"1\", \"TG\": \"1\",\n    \"AG\": \"2\", \"GA\": \"2\", \"CT\": \"2\", \"TC\": \"2\",\n    \"AT\": \"3\", \"TA\": \"3\", \"CG\": \"3\", \"GC\": \"3\"\n}\n\ndef solid_encode(seq):\n    return \"\".join(encoding[seq[i:i+2]] for i in range(len(seq)-1))\n\n# 示例\nseq = \"ACGTAC\"\nprint(solid_encode(seq))\n# 输出: 132132\n\n# 时间复杂度：O(n)", "lang": "Python", "principle": "①解决什么问题/用途：SOLiD测序用于高通量、高准确度的DNA测序，特别适合需要高碱基准确度的应用，如变异检测和癌症基因组研究。\n②核心思想（通俗类比）：SOLiD采用“双碱基编码”和连接测序，像用“颜色密码”记录每两个碱基的组合：每个探针的颜色由第1、2位碱基决定，因此每个碱基会被相邻两个探针“看两遍”，提高纠错能力。\n③主要步骤：1) 文库制备：可构建片段文库或配对末端文库。片段文库将DNA打断加接头；配对末端文库通过环化和酶切产生两端带接头的片段。2) 乳液PCR扩增微珠。3) 连接测序：引物与接头结合，连接酶连接荧光标记的8 bp探针，记录第1、2位编码区颜色，化学断裂探针后继续下一轮。\n④复杂度或关键参数：读长约50 bp，通量高；关键参数包括探针颜色编码、连接循环数和双碱基解码矩阵。\n⑤优缺点/适用场景：优点是准确度高（每个碱基判读两次），适合检测单碱基变异；缺点是读长短、数据分析复杂。适用于全基因组重测序、外显子组测序和癌症基因组研究。", "formula": [], "check": {"q": "关于SOLiD测序仪的文库制备，下列哪项说法正确？", "o": ["A. SOLiD只支持片段文库", "B. SOLiD只支持配对末端文库", "C. SOLiD支持片段文库或配对末端文库两种", "D. SOLiD不支持任何文库构建"], "a": "C", "e": "SOLiD测序仪支持两种测序文库：片段文库（fragment library）或配对末端文库（mate-paired library）。片段文库是将基因组DNA打断，两头加上接头制成文库；配对末端文库是将基因组DNA打断后与中间接头连接，再环化，然后用EcoP15酶切，使中间接头两端各有25～27bp碱基，再加上两端接头形成文库。"}, "cards": [{"front": "SOLiD测序仪支持哪两种测序文库？", "back": "片段文库和配对末端文库。片段文库是将基因组DNA打断，两头加上接头；配对末端文库是将基因组DNA打断后，与中间接头连接，再环化，然后用EcoP15酶切。", "mnemonic": "片段文库、配对末端文库", "useImg": false}]}, {"i": 6, "sec": "第二节 第二代测序原理", "title": "SOLiD连接测序原理", "notes": "本页介绍SOLiD测序仪的连接测序原理。SOLiD不使用聚合酶，而采用连接酶。通用引物与模板片段两端的接头序列互补结合，连接酶将一个荧光标记的8bp核酸探针连接到引物末端。探针5端标记4种颜色的荧光染料，3端第1、2位碱基构成编码区，决定探针颜色；第3-5位为随机碱基，第6-8位为可与任何碱基配对的特殊碱基。每次连接反应加入一种8碱基荧光探针，记录第1、2位编码区颜色信息，随后化学处理断裂探针第5、6位碱基间的化学键，进行下一轮连接。图14-3展示了双碱基编码矩阵：16种双碱基组合对应4种颜色，通过多轮连接和颜色解码，最终还原DNA序列。该技术通过双碱基编码，每个碱基被读取两次，提高准确度。", "page": 335, "level": "掌握", "img": "assets/img/ch14/p335.jpg", "anim": null, "fig": null, "points": ["SOLiD不使用聚合酶，而采用连接酶", "通用引物与模板片段两端的接头序列互补结合，连接酶将一个荧光标记的8bp核酸探针连接到引物末端", "探针5端标记4种颜色的荧光染料，3端第1、2位碱基构成编码区，决定探针颜色", "第3-5位为随机碱基，第6-8位为可与任何碱基配对的特殊碱基", "每次连接反应加入一种8碱基荧光探针，记录第1、2位碱基信息", "⚠️ 考点/易错点：核心考点：SOLiD采用连接酶而非聚合酶，8bp探针第1、2位为编码区决定颜色，第3-5位随机碱基，第6-8位特殊碱基。"], "code": "SOLiD连接测序核心步骤（伪代码）:\n1. 通用引物与模板接头互补结合\n2. for 每个测序循环:\n3.     加入一种荧光标记8bp探针\n4.     连接酶将探针连接到引物末端\n5.     记录探针第1、2位编码区颜色\n6.     化学断裂探针第5位与第6位之间，去除荧光标记\n7.     进入下一轮连接反应\n时间复杂度: O(L)，L为读长\n极简示例:\n模板: ...ACGT...\n探针编码区第1、2位决定颜色，如AC->红色\n记录颜色序列: 红, 蓝, 绿, ...\n", "lang": "伪代码/自然语言", "principle": "①解决什么问题/用途：本页介绍SOLiD连接测序的具体原理，解决如何通过连接酶和荧光探针读取DNA序列的问题。\n②核心思想（通俗类比）：连接测序像“用带颜色标签的拼图块去试拼”：每个8 bp探针的第1、2位碱基决定颜色，连接酶把探针接到引物末端，拍照记录颜色后切掉荧光部分，再继续拼下一块。\n③主要步骤：1) 通用引物与模板接头互补结合。2) 每个测序循环加入一种荧光标记的8 bp探针。3) 连接酶将探针连接到引物末端。4) 记录探针第1、2位编码区颜色。5) 化学断裂探针第5位与第6位之间，去除荧光标记。6) 进入下一轮连接反应。\n④复杂度或关键参数：时间复杂度O(L)，L为读长；关键参数包括探针设计、连接酶效率和颜色解码准确性。\n⑤优缺点/适用场景：优点是连接反应特异性高，双碱基编码提高准确度；缺点是步骤多、读长较短。适用于高准确度短读长测序。", "formula": [{"name": "双碱基编码探针结构", "expr": "探针 = [荧光标记]-(第1位碱基)(第2位碱基)-(第3~5位随机碱基)-(第6~8位通用碱基)", "note": "第1、2位为编码区决定荧光颜色；第3-5位随机；第6-8位可与任意碱基配对", "tex": "\\text{探针} = [\\text{荧光标记}]-(\\text{第1位碱基})(\\text{第2位碱基})-(\\text{第3\\textasciitilde 5位随机碱基})-(\\text{第6\\textasciitilde 8位通用碱基})"}], "check": {"q": "SOLiD连接测序原理中，连接酶连接的荧光标记核酸探针长度是多少？", "o": ["A. 4bp", "B. 6bp", "C. 8bp", "D. 10bp"], "a": "C", "e": "SOLiD不使用聚合酶而采用连接酶。通用引物与模板片段两端的接头序列互补结合，连接酶将一个荧光标记的8bp核酸探针连接到引物末端。探针5端标记4种颜色的荧光染料，3端第1、2位碱基构成编码区决定探针颜色。"}, "cards": [{"front": "SOLiD连接测序原理中，探针的结构是怎样的？", "back": "探针为8bp核酸探针，5端标记4种颜色的荧光染料，3端第1、2位碱基构成编码区，决定探针颜色；第3-5位为随机碱基，第6-8位为可与任何碱基配对的特殊碱基。", "mnemonic": "8bp探针，1-2位编码，3-5随机，6-8特殊", "useImg": false}]}, {"i": 7, "sec": "第二节 第二代测序原理", "title": "SOLiD数据分析及第二代测序技术应用概述", "notes": "本页首先介绍SOLiD数据分析：测序后获得4种颜色编码的原始序列，根据双碱基编码矩阵，只要知道DNA序列中任一位置的碱基类型，即可将颜色序列解码为碱基序列。双碱基编码使每个碱基判读两遍，减少错误，原始碱基准确度大于99.94%，为新一代测序中最高。随后进入第三节“第二代测序技术的应用”，概述第二代测序不仅用于测序，还能研究已知和未知物种基因组，快速获得基因组数据，鉴定转录基因、同源基因、新基因、表达水平、体细胞突变和可变剪切，深入重测序可了解疾病相关遗传作用。通过捕获序列片段，可应用于外显子测序等，推动各种组学诞生。最后介绍全基因组测序与重测序（DNA-seq）：可得到已知或未知基因组样本的DNA片段序列，通过组装获得全基因组图谱；重测序是对已知基因组序列的物种进行不同个体测序，分析个体或群体差异。高通量测序可跨过构建文库步骤，避免亚克隆偏差，依靠生物信息学分析。", "page": 336, "level": "掌握", "img": "assets/img/ch14/p336.jpg", "anim": null, "fig": null, "points": ["SOLiD数据分析：测序后获得4种颜色编码的原始序列，根据双碱基编码矩阵解码为碱基序列", "双碱基编码使每个碱基判读两遍，减少错误，原始碱基准确度大于99.94%，为新一代测序中最高", "第二代测序不仅用于测序，还能研究已知和未知物种基因组", "快速获得基因组信息", "⚠️ 考点/易错点：易错点：SOLiD双碱基编码使每个碱基判读两遍，准确度>99.94%为新一代测序最高；需知任一位置碱基类型即可解码颜色序列。"], "code": "# SOLiD颜色序列解码为碱基序列（Python风格伪代码）\n# 双碱基编码矩阵：4种颜色对应16种双碱基组合\n# 已知任一位置碱基，可逐步解码\n\ndef decode_solid(colors, start_base):\n    # colors: 颜色序列，如 ['R','B','G',...]\n    # start_base: 已知起始碱基，如 'A'\n    base_map = {\n        ('A','A'):'R', ('A','C'):'B', ('A','G'):'G', ('A','T'):'Y',\n        ('C','A'):'B', ('C','C'):'R', ('C','G'):'Y', ('C','T'):'G',\n        ('G','A'):'G', ('G','C'):'Y', ('G','G'):'R', ('G','T'):'B',\n        ('T','A'):'Y', ('T','C'):'G', ('T','G'):'B', ('T','T'):'R'\n    }\n    bases = [start_base]\n    for color in colors:\n        prev = bases[-1]\n        for (b1,b2), c in base_map.items():\n            if b1 == prev and c == color:\n                bases.append(b2)\n                break\n    return ''.join(bases)\n\n# 示例\ncolors = ['R','B','G']\nstart = 'A'\nprint(decode_solid(colors, start))  # 输出: AACG\n", "lang": "Python", "principle": "①解决什么问题/用途：本页介绍SOLiD数据分析方法及第二代测序技术的应用概述，解决如何将颜色编码序列解码为碱基序列，并说明二代测序的广泛应用。\n②核心思想（通俗类比）：双碱基编码像“用颜色记录相邻碱基对”，只要知道起始碱基，就能像查密码表一样逐步推出整个序列；每个碱基被两个颜色“覆盖”，相当于每个碱基判读两遍，降低错误。\n③主要步骤：1) 测序获得4种颜色编码的原始序列。2) 根据双碱基编码矩阵，已知任一位置碱基类型，逐步解码颜色序列为碱基序列。3) 应用：研究已知和未知物种基因组，鉴定转录基因、同源基因、新基因、表观遗传标记等。\n④复杂度或关键参数：解码复杂度O(L)，L为读长；关键参数包括起始碱基准确性、颜色矩阵和测序错误率。原始碱基准确度大于99.94%。\n⑤优缺点/适用场景：优点是准确度极高，适合检测单碱基变异；缺点是解码依赖起始碱基，数据分析复杂。适用于全基因组测序、转录组分析、表观遗传研究等。", "formula": [{"name": "双碱基编码解码", "expr": "若已知参考序列某位置碱基 b_i，则 b_{i+1} = decode(c_i, b_i)", "note": "c_i为第i次连接测得的颜色编码；通过双碱基编码矩阵由前一碱基和颜色推出下一碱基；每个碱基被读取两次，准确度>99.94%", "tex": "\\text{若已知参考序列某位置碱基 } b_i \\text{，则 } b_{i+1} = \\mathrm{decode}(c_i, b_i)"}], "check": {"q": "关于SOLiD数据分析及第二代测序技术应用，下列哪项说法正确？", "o": ["A. SOLiD测序后获得4种颜色编码的原始序列，双碱基编码使每个碱基判读两遍，原始碱基准确度大于99.94%", "B. SOLiD测序后直接获得碱基序列，无需解码", "C. 双碱基编码使每个碱基只判读一遍", "D. 第二代测序只能用于测序，不能研究基因表达"], "a": "A", "e": "SOLiD测序后获得4种颜色编码的原始序列，根据双碱基编码矩阵，只要知道DNA序列中任一位置的碱基类型，即可将颜色序列解码为碱基序列。双碱基编码使每个碱基判读两遍，减少错误，原始碱基准确度大于99.94%，为新一代测序中最高。"}, "cards": [{"front": "SOLiD测序的双碱基编码有什么优势？", "back": "双碱基编码使每个碱基判读两遍，减少错误，原始碱基准确度大于99.94%，为新一代测序中最高。", "mnemonic": "双碱基编码，准确度最高", "useImg": false}]}, {"i": 8, "sec": "第二节 第二代测序原理", "title": "小RNA测序、lncRNA测序及ChIP-seq", "notes": "本页继续介绍第二代测序的应用。首先是小RNA测序：对small RNA进行大规模测序分析，可获得全基因组水平的microRNA图谱，实现新microRNA鉴定、差异表达分析、microRNA聚类和表达谱分析等。长链非编码RNA（lncRNA）是一类长度超过200nt的非编码RNA，不编码蛋白质，但能以RNA形式在转录水平、转录后水平及表观修饰水平调控基因表达。多数lncRNA无polyA尾，而常用RNA-seq利用polyA尾捕获转录本，因此主要获得编码蛋白质的转录本，lncRNA很少。目前针对ncRNA测序最好的策略是rRNA消解法构建文库，但该方法不成熟、费用高，专门针对lncRNA的测序很少。接着介绍表观组学测序和染色质免疫共沉淀测序（ChIP-seq）：ChIP是研究体内蛋白质与DNA相互作用的有力工具，用于定位全基因组范围内的结合位点或表观遗传学修饰。图中展示了ChIP-seq流程：DNA片段化、免疫共沉淀、纯化、接头连接、PCR扩增、Illumina Genome Analyzer测序、图像识别和序列信息分析。", "page": 337, "level": "理解", "img": "assets/img/ch14/p337.jpg", "anim": null, "fig": null, "points": ["小RNA测序：对small RNA进行大规模测序分析，可获得全基因组水平的microRNA图谱", "实现新microRNA鉴定、差异表达分析、microRNA聚类和表达谱分析等", "长链非编码RNA（lncRNA）是一类长度超过200nt的非编码RNA，不编码蛋白质", "lncRNA能以RNA形式在转录水平、转录后水平及表观修饰水平调控基因表达", "⚠️ 考点/易错点：小RNA测序可获全基因组microRNA图谱；lncRNA长度>200nt且不编码蛋白，多数无polyA尾，故常用polyA捕获的RNA-seq难以有效富集lncRNA。"], "code": "# 小RNA测序分析流程（Linux命令示例）\n# 1. 质控\nfastqc smallRNA.fastq\n# 2. 去除接头\ncutadapt -a TGGAATTCTCGGGTGCCAAGG -o trimmed.fastq smallRNA.fastq\n# 3. 比对到参考基因组\nbowtie -f -v 1 -m 1 --best --strata genome_index trimmed.fastq aligned.bam\n# 4. 鉴定已知microRNA\nmiRDeep2.pl trimmed.fastq genome.fa aligned.bam mature_miRNA.fa none 2> report.log\n# 5. 差异表达分析（R/DESeq2示例）\n# library(DESeq2)\n# dds <- DESeqDataSetFromMatrix(countData, colData, design=~condition)\n# dds <- DESeq(dds)\n# res <- results(dds)\n", "lang": "Shell/Linux + R", "principle": "①解决什么问题/用途：本页介绍小RNA测序和lncRNA测序的分析方法，用于在全基因组水平鉴定microRNA、分析差异表达、聚类和表达谱，以及研究长度超过200nt、不编码蛋白质但能调控基因表达的长链非编码RNA。\n②核心思想：小RNA测序像“筛沙子找金子”，先把小RNA从总RNA中富集并测序，再通过接头去除、比对和定量找出有意义的microRNA；lncRNA测序则像“找暗物质”，关注不编码蛋白但可能调控基因的RNA分子。\n③主要步骤：小RNA测序流程包括质控（fastqc）、去除3'接头（cutadapt）、比对到参考基因组（bowtie）、定量和差异分析；lncRNA分析需注意多数lncRNA无polyA尾，常采用rRNA去除建库，再拼接、注释和表达分析。\n④复杂度或关键参数：比对允许错配数、接头序列、比对唯一性等是关键参数；计算复杂度主要取决于测序读长数和参考基因组大小。\n⑤优缺点/适用场景：小RNA测序灵敏度高、可发现新microRNA，但依赖接头去除和注释质量；lncRNA测序能发现新lncRNA，但组装和功能注释困难，适合研究调控机制和疾病标志物。", "formula": [], "check": {"q": "关于小RNA测序和lncRNA测序，下列哪项说法正确？", "o": ["A. 小RNA测序不能获得全基因组水平的microRNA图谱", "B. lncRNA是一类长度超过200nt的非编码RNA，不编码蛋白质", "C. 多数lncRNA有polyA尾，常用RNA-seq利用polyA尾捕获转录本", "D. lncRNA不能调控基因表达"], "a": "B", "e": "长链非编码RNA（lncRNA）是一类长度超过200nt的非编码RNA，不编码蛋白质，但能以RNA形式在转录水平、转录后水平及表观修饰水平调控基因表达。多数lncRNA无polyA尾，而常用RNA-seq利用polyA尾捕获转录本。小RNA测序可获得全基因组水平的microRNA图谱。"}, "cards": [{"front": "小RNA测序可以获得哪些信息？", "back": "可获得全基因组水平的microRNA图谱，实现新microRNA鉴定、差异表达分析、microRNA聚类和表达谱分析等。", "mnemonic": "microRNA图谱、鉴定、表达分析", "useImg": false}]}, {"i": 9, "sec": "第二节 第二代测序原理", "title": "DNA甲基化测序方法", "notes": "本页介绍DNA甲基化测序。重硫酸盐测序法是一种化学转变法，原理是重硫酸盐处理后的基因组中未甲基化的胞嘧啶转换为尿嘧啶，而甲基化的胞嘧啶不变。主要方法有全基因组重硫酸盐测序（MethylC-seq或BS-seq）和简化表达重硫酸盐测序（RRBS）。随着测序发展，发现不仅5mC抵抗重硫酸盐转化，5-羟甲基胞嘧啶（5hmC，5mC和胞嘧啶的中间态）也抵抗转化。随后提出hMeDIP-seq，利用抗体免疫共沉淀捕获5hmC序列，但分辨率和质量不佳。2013年提出氧化重硫酸测序（oxBS-seq）和TET相关的重硫酸测序（TAB-seq）。例如oxBS-seq中，5hmC先被化学氧化成5fC，再经重硫酸盐处理转化为尿嘧啶。利用oxBS-seq得到的DNA甲基化片段比MethylC-seq少，少的部分即5hmC。图14-5展示了Illumina Genome Analyzer MeDIP-seq测序过程：DNA片段化、接头连接、免疫沉淀、测序、图像识别和甲基化序列信息分析。", "page": 338, "level": "理解", "img": "assets/img/ch14/p338.jpg", "anim": null, "fig": null, "points": ["重硫酸盐测序法是一种化学转变法，原理是重硫酸盐处理后的基因组中未甲基化的胞嘧啶转换为尿嘧啶，而甲基化的胞嘧啶不变", "主要方法有全基因组重硫酸盐测序（MethylC-seq或BS-seq）和简化表达重硫酸盐测序（RRBS）", "5-羟甲基胞嘧啶（5hmC，5mC和胞嘧啶的中间态）也抵抗重硫酸盐转化", "⚠️ 考点/易错点：重硫酸盐测序中未甲基化C转为U、甲基化C不变；易错点：5hmC也抵抗重硫酸盐转化，故BS-seq无法区分5mC与5hmC。"], "code": "# 重硫酸盐测序数据分析核心步骤（Python伪代码）\n# 1. 重硫酸盐处理：未甲基化C->U，甲基化C不变\n# 2. 测序后比对：C->T转换\n# 3. 计算甲基化水平\n\ndef bisulfite_align(reads, ref):\n    # 将参考基因组中所有C转换为T，得到T基因组\n    ref_T = ref.replace('C', 'T')\n    # 将reads中C转换为T\n    reads_T = [r.replace('C', 'T') for r in reads]\n    # 比对reads_T到ref_T\n    alignments = align(reads_T, ref_T)\n    return alignments\n\ndef methylation_level(alignments, ref):\n    # 统计每个C位点的甲基化比例\n    meth = {}\n    for read, pos in alignments:\n        if ref[pos] == 'C':\n            if read[pos] == 'C':\n                meth[pos] = meth.get(pos, [0,0])\n                meth[pos][0] += 1  # 甲基化\n            elif read[pos] == 'T':\n                meth[pos] = meth.get(pos, [0,0])\n                meth[pos][1] += 1  # 未甲基化\n    return {p: v[0]/(v[0]+v[1]) for p,v in meth.items()}\n", "lang": "Python", "principle": "①解决什么问题/用途：本页介绍DNA甲基化测序方法，用于检测基因组中5-甲基胞嘧啶（5mC）和5-羟甲基胞嘧啶（5hmC）等表观遗传修饰，研究基因表达调控、发育和疾病。\n②核心思想：重硫酸盐测序像“给未甲基化的C换衣服”，未甲基化的胞嘧啶被转化为尿嘧啶，而甲基化的胞嘧啶保持不变；测序后C→T的转换就代表未甲基化，C不变则代表甲基化。\n③主要步骤：重硫酸盐处理DNA，使未甲基化C变为U；PCR扩增后U变为T；测序；将reads与参考基因组比对时，需将参考基因组C转为T或使用专门比对软件；计算每个位点甲基化水平。全基因组重硫酸盐测序（BS-seq）覆盖全基因组，RRBS则通过酶切富集CpG密集区。\n④复杂度或关键参数：关键参数包括重硫酸盐转化率、测序深度、比对允许的C/T差异；全基因组测序成本高，RRBS降低成本但只覆盖部分区域。\n⑤优缺点/适用场景：BS-seq全面但昂贵；RRBS经济高效，适合差异甲基化区域研究；hMeDIP-seq利用抗体富集5hmC，适合研究5hmC分布，但分辨率有限。", "formula": [{"name": "重硫酸盐转化反应", "expr": "C + HSO₃⁻ → U + HSO₃⁻（未甲基化胞嘧啶）；5mC + HSO₃⁻ → 5mC（甲基化胞嘧啶不变）", "note": "C为胞嘧啶，U为尿嘧啶，5mC为5-甲基胞嘧啶。", "tex": "\\mathrm{C} + \\mathrm{HSO_3^-} \\rightarrow \\mathrm{U} + \\mathrm{HSO_3^-} \\quad (\\text{未甲基化胞嘧啶});\\quad \\mathrm{5mC} + \\mathrm{HSO_3^-} \\rightarrow \\mathrm{5mC} \\quad (\\text{甲基化胞嘧啶不变})"}, {"name": "5hmC抗转化", "expr": "5hmC + HSO₃⁻ → 5hmC", "note": "5hmC为5-羟甲基胞嘧啶，也抵抗重硫酸盐转化。", "tex": "\\mathrm{5hmC} + \\mathrm{HSO_3^-} \\rightarrow \\mathrm{5hmC}"}], "check": {"q": "关于DNA甲基化测序方法，下列哪项说法正确？", "o": ["A. 重硫酸盐处理后的基因组中甲基化的胞嘧啶转换为尿嘧啶", "B. 重硫酸盐处理后的基因组中未甲基化的胞嘧啶转换为尿嘧啶，而甲基化的胞嘧啶不变", "C. 5-羟甲基胞嘧啶（5hmC）不能抵抗重硫酸盐转化", "D. hMeDIP-seq分辨率和质量均优于其他方法"], "a": "B", "e": "重硫酸盐测序法原理是重硫酸盐处理后的基因组中未甲基化的胞嘧啶转换为尿嘧啶，而甲基化的胞嘧啶不变。主要方法有全基因组重硫酸盐测序（MethylC-seq或BS-seq）和简化表达重硫酸盐测序（RRBS）。5hmC也抵抗重硫酸盐转化。hMeDIP-seq利用抗体免疫共沉淀捕获5hmC序列，但分辨率和质量不佳。"}, "cards": [{"front": "重硫酸盐测序法的原理是什么？", "back": "重硫酸盐处理后的基因组中未甲基化的胞嘧啶转换为尿嘧啶，而甲基化的胞嘧啶不变。主要方法有全基因组重硫酸盐测序（MethylC-seq或BS-seq）和简化表达重硫酸盐测序（RRBS）。", "mnemonic": "未甲基化C→U，甲基化C不变", "useImg": false}]}, {"i": 10, "sec": "第二节 第二代测序原理", "title": "多因素数据统计分析、RASH及NGS数据获取", "notes": "本页首先介绍多因素数据统计分析（two-way ANOVA）：根据一个以上不同条件综合评判，筛选多个条件对两组样品造成的差异基因。接着介绍RASH：用挑选的差异基因的表达情况计算样品间的相关性，同一类样品能通过聚类出现在同一个簇中，聚在同一簇的基因可能具有类似生物学功能。常用聚类方法有层次聚类、K-means聚类和DBSCAN算法。然后介绍机器学习及其他分析方法：由于生物数据复杂性，可根据样本数据和目的采用主成分分析、遗传算法、人工神经网络、支持向量机、自组织映射、置信网络、隐马尔可夫模型等，数据挖掘中可能用到多种方法。综上，第二代测序数据处理需要高性能计算机和精通多种程序语言的生物信息学家，其发展也推动了生物信息学发展。最后进入第四节“生物信息学在第二代测序中的应用”，介绍NGS数据获取：可根据研究需要自行设计文库测序，2007年NCBI建立了新一代测序结果子数据库，数据可提交至NCBI SRA、EBI ENA和DDBJ DTA。其他获取途径见表14-2，主要生物信息学工具见表14-3。", "page": 339, "level": "了解", "img": "assets/img/ch14/p339.jpg", "anim": null, "fig": null, "points": ["多因素数据统计分析（two-way ANOVA）：根据一个以上不同条件综合评判，筛选多个条件对两组样品造成的差异基因", "RASH：用挑选的差异基因的表达情况计算样品间的相关性，同一类样品能通过聚类出现在同一个簇中", "聚在同一簇的基因可能具有类似生物学功能", "常用聚类方法有层次聚类、K-means聚类和DBSCAN算法", "机器学习及其他分析方法", "⚠️ 考点/易错点：two-way ANOVA用于一个以上不同条件综合筛选差异基因；RASH通过差异基因表达计算样品相关性并聚类，同一簇基因可能功能相似。"], "code": "# 多因素数据统计分析：two-way ANOVA（R代码示例）\n# 假设数据框df包含表达量、因素A、因素B\ndf <- data.frame(\n  expr = c(10,12,15,9,11,14,20,22,25,19,21,24),\n  factorA = factor(rep(c('ctrl','treat'), each=6)),\n  factorB = factor(rep(c('cond1','cond2','cond3'), times=4))\n)\n# 双因素方差分析\nmodel <- aov(expr ~ factorA * factorB, data=df)\nsummary(model)\n\n# RASH：相关性聚类（Python示例）\nimport pandas as pd\nfrom scipy.cluster.hierarchy import linkage, dendrogram\nimport matplotlib.pyplot as plt\n# 假设expr_matrix为基因表达矩阵（行=基因，列=样品）\n# 计算样品间相关性\ncorr = expr_matrix.corr()\n# 层次聚类\nZ = linkage(corr, method='average')\ndendrogram(Z, labels=corr.columns)\nplt.show()\n", "lang": "R + Python", "principle": "①解决什么问题/用途：本页介绍多因素数据统计分析、RASH聚类和机器学习等方法，用于从复杂生物数据中筛选差异基因、发现样本分群和基因功能模块。\n②核心思想：two-way ANOVA像“同时考虑两个调料对菜味的影响”，不仅看每个因素单独作用，还看因素间交互作用；RASH聚类像“物以类聚”，用差异基因表达计算样本相关性，同类样本聚在一起，同簇基因可能功能相似。\n③主要步骤：two-way ANOVA：建立包含两个因素及交互项的线性模型，计算F统计量和p值，筛选显著差异基因；RASH：选择差异基因，计算样本间相关性，用层次聚类、K-means或DBSCAN聚类，解释簇功能。\n④复杂度或关键参数：ANOVA关键参数是显著性阈值和多重检验校正；聚类关键参数是距离度量、簇数K、DBSCAN的邻域半径和最小点数。\n⑤优缺点/适用场景：two-way ANOVA适合多条件实验设计；层次聚类直观但计算量较大，K-means快速但需预设K，DBSCAN能发现任意形状簇但对参数敏感。", "formula": [{"name": "双因素方差分析模型", "expr": "y_ijk = μ + α_i + β_j + (αβ)_ij + ε_ijk", "note": "y_ijk为观测值，μ为总均值，α_i为因素A效应，β_j为因素B效应，(αβ)_ij为交互效应，ε_ijk为随机误差。", "tex": "y_{ijk} = \\mu + \\alpha_i + \\beta_j + (\\alpha\\beta)_{ij} + \\varepsilon_{ijk}"}, {"name": "样本间相关性", "expr": "r_xy = Σ(x_i - x̄)(y_i - ȳ) / √[Σ(x_i - x̄)² Σ(y_i - ȳ)²]", "note": "r_xy为样本x与y的相关系数，x_i、y_i为表达值，x̄、ȳ为均值。", "tex": "r_{xy} = \\frac{\\sum (x_i - \\bar{x})(y_i - \\bar{y})}{\\sqrt{\\sum (x_i - \\bar{x})^2 \\sum (y_i - \\bar{y})^2}}"}, {"name": "K-means聚类目标函数", "expr": "J = Σ_{k=1}^{K} Σ_{x_i ∈ C_k} ||x_i - μ_k||²", "note": "K为簇数，C_k为第k簇，μ_k为第k簇质心，x_i为样本点。", "tex": "J = \\sum_{k=1}^{K} \\sum_{x_i \\in C_k} \\|x_i - \\mu_k\\|^2"}], "check": {"q": "关于多因素数据统计分析和RASH，下列哪项说法正确？", "o": ["A. two-way ANOVA只能分析一个条件对两组样品造成的差异基因", "B. RASH是用挑选的差异基因的表达情况计算样品间的相关性，同一类样品能通过聚类出现在同一个簇中", "C. 常用聚类方法只有层次聚类一种", "D. 机器学习方法不能用于生物数据分析"], "a": "B", "e": "多因素数据统计分析（two-way ANOVA）根据一个以上不同条件综合评判，筛选多个条件对两组样品造成的差异基因。RASH用挑选的差异基因的表达情况计算样品间的相关性，同一类样品能通过聚类出现在同一个簇中，聚在同一簇的基因可能具有类似生物学功能。常用聚类方法有层次聚类、K-means聚类和DBSCAN算法。"}, "cards": [{"front": "RASH分析中常用的聚类方法有哪些？", "back": "层次聚类、K-means聚类和DBSCAN算法。", "mnemonic": "层次、K-means、DBSCAN", "useImg": false}]}, {"i": 11, "sec": "第二节 第二代测序原理", "title": "NGS数据分析的主要生物信息学工具", "notes": "本页为表14-3，列出NGS数据分析的主要生物信息学工具，包括工具名称、说明和网址。工具涵盖序列匹配、组装和可视化：Velvet用于短片段序列的重新组装拼接；EULER用于Sanger测序和NGS混合片段组装；MOSAIK用于NGS序列匹配；RMAP将短片段匹配到参考基因组；SHARCGS用于短片段重组装；SOAP将有缺口或无缺口片段匹配到参考基因组，能进行单一或末端匹配的重测序、smRNA发现及mRNA标签序列匹配；TOPS用于序列匹配；VCAKE用于短片段组装；JMP Genomics用于NGS数据可视化及统计分析；还有挖掘序列变异的工具。表中还包含二维码和网址。读表时注意工具功能分类：组装、匹配、可视化、变异挖掘等，可根据研究需求选择合适工具。", "page": 340, "level": "了解", "img": "assets/img/ch14/p340.jpg", "anim": null, "fig": "表14-3列出NGS数据分析的主要生物信息学工具。查看时注意工具名称、功能说明和网址，根据分析需求选择合适工具。", "points": ["表14-3列出NGS数据分析的主要生物信息学工具，包括工具名称、说明和网址", "工具涵盖序列匹配、组装和可视化", "Velvet用于短片段序列的重新组装拼接", "EULER用于Sanger测序和NGS混合片段组装", "MOSAIK用于NGS序列匹配；RMAP将短片段匹配到参考基因组；SHARCGS用于短片段重组装；SOAP将有缺口或无缺口片段匹配到参考基因组", "⚠️ 考点/易错点：需区分各NGS工具用途：Velvet用于短片段重组装，MOSAIK用于序列匹配，SOAP可匹配有/无缺口片段到参考基因组，EULER用于Sanger与NGS混合组装。"], "code": "# NGS常用工具命令示例\n# Velvet: 短片段组装\nvelveth output_dir 21 -fastq reads.fastq\nvelvetg output_dir -cov_cutoff auto\n\n# EULER: 混合片段组装\neuler -reads reads.fasta -output assembly\n\n# MOSAIK: NGS序列匹配\nmosaik align -ref reference.fa -in reads.fastq -out aligned.bam\n\n# RMAP: 短片段匹配到参考基因组\nrmap -h reference.fa reads.fastq > output.txt\n\n# SHARCGS: 短片段重组装\nsharcgs -reads reads.fasta -o assembly\n\n# SOAP: 片段匹配\nsoap -a reads.fastq -d reference.fa -o output.soap -p 4\n", "lang": "Shell/Linux", "principle": "①解决什么问题/用途：本页列出NGS数据分析的主要生物信息学工具，涵盖序列匹配、组装和可视化，帮助研究者根据任务选择合适软件。\n②核心思想：这些工具像“不同用途的厨房电器”，Velvet、EULER、SHARCGS用于组装，MOSAIK、RMAP、SOAP用于比对，各有所长。\n③主要步骤：以Velvet为例，先用velveth构建k-mer哈希，再用velvetg构建De Bruijn图并输出contig；MOSAIK和SOAP将reads比对到参考基因组，输出比对结果；EULER用于混合片段组装。\n④复杂度或关键参数：Velvet关键参数是k-mer长度和覆盖度 cutoff；SOAP关键参数是允许错配数、是否末端匹配；组装复杂度随k-mer和基因组重复度增加。\n⑤优缺点/适用场景：Velvet适合短读长从头组装，SOAP适合重测序和SNP发现，MOSAIK适合NGS序列匹配；工具选择取决于读长、参考基因组有无和计算资源。", "formula": [], "check": {"q": "在表14-3列出的NGS数据分析工具中，哪个工具用于短片段序列的重新组装拼接？", "o": ["A. MOSAIK", "B. RMAP", "C. Velvet", "D. SOAP"], "a": "C", "e": "表14-3中，Velvet用于短片段序列的重新组装拼接；MOSAIK用于NGS序列匹配；RMAP将短片段匹配到参考基因组；SOAP将有缺口或无缺口片段匹配到参考基因组。"}, "cards": [{"front": "表14-3中列出的NGS数据分析工具主要涵盖哪些功能？", "back": "序列匹配、组装和可视化。例如Velvet用于短片段序列的重新组装拼接；EULER用于Sanger测序和NGS混合片段组装；MOSAIK用于NGS序列匹配；RMAP将短片段匹配到参考基因组；SHARCGS用于短片段重组装；SOAP将有缺口或无缺口片段匹配到参考基因组。", "mnemonic": "匹配、组装、可视化", "useImg": false}]}, {"i": 12, "sec": "第四节 生物信息学在第二代测序中的应用", "title": "RNA-seq生物信息学分析流程（无参考基因组与有参考基因组）", "notes": "本页介绍RNA-seq中的生物信息学分析，重点区分无参考基因组和有参考基因组两种策略。无参考基因组转录组分析（图14-6）流程包括：测序数据产量统计、去除冗余数据、数据成分与质量评估；采用Cufflinks等RNA-seq分析软件重建转录本；计算Contig和Scaffold长度分布；Unigene长度分布、功能注释、GO分类；代谢通路分析；Unigene表达差异分析及差异表达Unigene的GO功能注释。图14-6展示mRNA经片段化、逆转录、测序得到短读长，包括外显子读长、连接区读长和PolyA读长，再经从头组装定位到转录本。有参考基因组转录组分析（图14-7）流程包括：测序数据产量统计、去除冗余数据、与参考基因组比对后的注释信息；采用Cufflinks等重建转录本；Reads在基因组上的分布；测序深度分布、测序随机性评估；基因差异表达分析；新基因预测、可变剪接鉴定、基因融合鉴定、已知和新的非编码RNA鉴定。small RNA和miRNA测序分析包括small RNA分类注释，与Rfam数据库及GeneBank比对等。", "page": 341, "level": "掌握", "img": "assets/img/ch14/p341.jpg", "anim": null, "fig": "图14-6展示无参考基因组转录组分析流程。看图时注意从测序数据到功能注释的各个步骤，理解无参考基因组情况下的组装和注释策略。", "points": ["RNA-seq中的生物信息学分析，重点区分无参考基因组和有参考基因组两种策略", "无参考基因组转录组分析流程包括：测序数据产量统计、去除冗余数据、数据成分与质量评估", "采用Cufflinks等RNA-seq分析软件重建转录本", "计算Contig和Scaffold长度分布；Unigene长度分布、功能注释、GO分类", "代谢通路分析；Unigene表达分析", "⚠️ 考点/易错点：无参考基因组RNA-seq分析流程核心是de novo重建转录本（如Cufflinks）并做Unigene功能注释、GO分类、代谢通路及差异表达分析。"], "code": "# RNA-seq 无参考基因组分析流程（简化伪代码）\n# 输入: reads.fq\n# 输出: unigene 表达矩阵 + 注释\n\n1. fastqc reads.fq                      # 质量评估\n2. trimmomatic / cutadapt               # 去冗余、去接头\n3. trinity --seqType fq --left reads.fq --CPU 8 --output trinity_out  # de novo 组装\n4. cd-hit-est -i trinity.fasta -o unigene.fasta -c 0.95  # 去冗余得到 Unigene\n5. blastx unigene.fasta -db nr -out blast.out           # 功能注释\n6. blast2go / interproscan                              # GO 分类\n7. kegg_annotation unigene.fasta                        # 代谢通路\n8. bowtie2 + RSEM / salmon                              # 表达定量\n9. edgeR / DESeq2                                       # 差异表达\n\n# 时间复杂度: 组装 O(N log N) ~ O(N^2)，比对 O(N*M)\n# 极简示例: trinity --seqType fq --left r1.fq --right r2.fq --output out", "lang": "Shell/Linux + 伪代码/自然语言", "principle": "①解决什么问题/用途：本页介绍无参考基因组RNA-seq分析流程，用于没有参考基因组物种的转录组研究，包括转录本重建、功能注释和差异表达分析。\n②核心思想：无参考基因组分析像“没有地图拼拼图”，先测序得到大量短reads，再通过组装把它们拼成较长的转录本（Unigene），然后注释和比较表达。\n③主要步骤：质控（fastqc）、去接头和低质量序列（trimmomatic/cutadapt）、从头组装（Trinity）、计算Contig/Scaffold和Unigene长度分布、功能注释（GO、KEGG）、差异表达分析及富集分析。\n④复杂度或关键参数：Trinity组装关键参数包括k-mer长度、CPU数和最小contig长度；复杂度高，内存消耗大，受测序深度和物种复杂度影响。\n⑤优缺点/适用场景：无需参考基因组，适合非模式生物；但组装可能产生嵌合体、冗余和错误，注释依赖公共数据库，适合探索性研究。", "formula": [], "check": {"q": "关于无参考基因组转录组分析流程，下列哪项说法正确？", "o": ["A. 无参考基因组分析不需要进行测序数据产量统计", "B. 无参考基因组分析流程包括测序数据产量统计、去除冗余数据、数据成分与质量评估，采用Cufflinks等软件重建转录本", "C. 无参考基因组分析不能进行GO分类", "D. 无参考基因组分析不需要进行代谢通路分析"], "a": "B", "e": "无参考基因组转录组分析流程包括：测序数据产量统计、去除冗余数据、数据成分与质量评估；采用Cufflinks等RNA-seq分析软件重建转录本；计算Contig和Scaffold长度分布；Unigene长度分布、功能注释、GO分类；代谢通路分析；Unigene表达差异分析及差异表达Unigene的GO功能注释。"}, "cards": [{"front": "无参考基因组转录组分析流程包括哪些主要步骤？", "back": "测序数据产量统计、去除冗余数据、数据成分与质量评估；采用Cufflinks等软件重建转录本；计算Contig和Scaffold长度分布；Unigene长度分布、功能注释、GO分类；代谢通路分析；Unigene表达分析。", "mnemonic": "统计→去冗余→评估→重建→注释→通路→表达", "useImg": false}]}, {"i": 13, "sec": "第四节 生物信息学在第二代测序中的应用", "title": "有参考基因组RNA-seq分析策略与ChIP-seq分析", "notes": "本页继续讲解有参考基因组的RNA-seq分析策略（图14-7），左图为“先匹配再组装”，右图为“先组装再匹配”。先匹配再组装是将读长先比对到参考基因组，再合并分散片段为转录本；先组装再匹配是先将读长组装成转录本，再比对到基因组。随后介绍ChIP-seq相关分析：统计样品Unique mapped reads在重复区域、基因区间、基因上的分布情况和覆盖深度；统计分析每个样品中与基因相关的Peak信息并找到这些基因；对Peak相关基因进行GO功能显著性富集分析；不同样本中基因的ChIP-seq信息差异分析；转录因子结合区域分析和motif挖掘（图14-8）；甲基化和组蛋白修饰检测比较；不同表观遗传修饰对基因表达调控的影响（图14-9）。图14-8展示motif分析流程：被测序的短读长比对到参考基因组，经计算后合并为新的motif。", "page": 342, "level": "掌握", "img": "assets/img/ch14/p342.jpg", "anim": null, "fig": "图14-7展示有参考基因组RNA-seq分析的两种策略。看图时注意左右两图的区别：左图先比对再组装，右图先组装再比对。", "points": ["有参考基因组的RNA-seq分析策略（图14-7），左图为“先匹配再组装”，右图为“先组装再匹配”", "先匹配再组装是将读长先比对到参考基因组，再合并分散片段为转录本", "先组装再匹配是先将读长组装成转录本，再比对到基因组", "ChIP-seq相关分析：统计样品Unique mapped reads在重复区域、基因区间、基因上的分布情况和覆盖深度", "⚠️ 考点/易错点：有参考基因组RNA-seq有两种策略：先匹配再组装（先比对再合并为转录本）与先组装再匹配（先组装转录本再比对基因组），二者顺序相反易混。"], "code": "# 有参考基因组 RNA-seq 两种策略\n# 策略A: 先匹配再组装 (align-then-assemble)\nhisat2 -x genome_index -1 r1.fq -2 r2.fq -S aln.sam\nsamtools sort -o aln.bam aln.sam\nstringtie aln.bam -G ref.gtf -o merged.gtf\n\n# 策略B: 先组装再匹配 (assemble-then-align)\ntrinity --seqType fq --left r1.fq --right r2.fq --output trinity_out\ngmap -d genome_index trinity_out/Trinity.fasta > asm.sam\n\n# ChIP-seq 分析\nbowtie2 -x genome_index -U chip.fq -S chip.sam\nsamtools sort -o chip.bam chip.sam\nmacs2 callpeak -t chip.bam -c input.bam -g hs -n peak\n# 统计 Unique mapped reads 分布\nbedtools intersect -a chip.bam -b repeats.bed -c\n# 时间复杂度: 比对 O(N*M)，Peak calling O(N log N)", "lang": "Shell/Linux", "principle": "①解决什么问题/用途：本页介绍有参考基因组RNA-seq的两种分析策略及ChIP-seq分析，用于已知基因组物种的转录本定量和蛋白质-DNA结合位点研究。\n②核心思想：有参考基因组RNA-seq像“有地图导航”，可先比对再组装或先组装再比对；ChIP-seq像“用磁铁吸出特定蛋白结合的DNA片段”，再测序定位结合位点。\n③主要步骤：策略A先匹配再组装：hisat2比对→samtools排序→stringtie组装；策略B先组装再匹配：先组装转录本再比对基因组。ChIP-seq分析包括比对、去除重复、Peak calling、统计Peak在基因区间和重复区域的分布、覆盖深度和基因相关Peak信息。\n④复杂度或关键参数：比对关键参数是错配数、唯一比对；Peak calling关键参数是峰宽、富集倍数和FDR；ChIP-seq需对照样本。\n⑤优缺点/适用场景：先匹配再组装利用参考基因组，准确度高；先组装再匹配能发现新转录本但计算复杂。ChIP-seq适合研究转录因子结合和组蛋白修饰，但依赖抗体质量和对照设计。", "formula": [], "check": {"q": "关于有参考基因组RNA-seq分析策略，下列哪项说法正确？", "o": ["A. 只有“先匹配再组装”一种策略", "B. 只有“先组装再匹配”一种策略", "C. 包括“先匹配再组装”和“先组装再匹配”两种策略", "D. 有参考基因组分析不需要比对到参考基因组"], "a": "C", "e": "有参考基因组的RNA-seq分析策略包括两种：先匹配再组装是将读长先比对到参考基因组，再合并分散片段为转录本；先组装再匹配是先将读长组装成转录本，再比对到基因组。"}, "cards": [{"front": "有参考基因组RNA-seq分析的两种策略是什么？", "back": "先匹配再组装：将读长先比对到参考基因组，再合并分散片段为转录本；先组装再匹配：先将读长组装成转录本，再比对到基因组。", "mnemonic": "先匹配再组装 vs 先组装再匹配", "useImg": false}]}, {"i": 14, "sec": "第四节 生物信息学在第二代测序中的应用", "title": "表观遗传修饰测序分析与NGS功能基因组学应用", "notes": "本页展示利用第二代测序分析表观遗传修饰（图14-9），包括BS-seq流程和ChIP-seq流程。BS-seq流程：DNA经亚硫酸氢盐处理，未甲基化的胞嘧啶C转化为尿嘧啶U，甲基化的C保持不变，经PCR扩增后测序，再将读长比对到基因组，用于检测DNA甲基化。ChIP-seq流程：蛋白质与DNA结合，经超声波处理、抗体免疫沉淀、提纯DNA、连接接头、PCR扩增后测序，将读长比对到基因组，用于检测转录因子结合位点和组蛋白修饰。图14-9还展示UCSC Genome Browser和Anno-J Browser等可视化工具，以及染色体位置上的信号峰。随后介绍NGS在功能基因组学中的应用：NGS可得到基因水平、转录水平和蛋白质水平的不同数据，利用生物信息学手段综合不同水平进行研究，结果更具生物学意义。图14-10是基于NGS在功能基因组学中综合研究的例子。最后引出第五节生物信息学新技术与发展趋势，指出二代、三代测序技术推动研究模式革新，生物信息学研究正向精准化发展。", "page": 343, "level": "理解", "img": "assets/img/ch14/p343.jpg", "anim": null, "fig": "图14-9展示表观遗传修饰测序分析流程。看图时注意BS-seq和ChIP-seq两个流程的步骤差异，理解各自用于检测DNA甲基化和蛋白质-DNA结合。", "points": ["利用第二代测序分析表观遗传修饰（图14-9），包括BS-seq流程和ChIP-seq流程", "BS-seq流程：DNA经亚硫酸氢盐处理，未甲基化的胞嘧啶C转化为尿嘧啶U，甲基化的C保持不变", "经PCR扩增后测序，再将读长比对到基因组，用于检测DNA甲基化", "ChIP-seq流程：蛋白质与DNA结合，经超声波处理、抗体免疫沉淀、提纯DNA、连接接头、PCR扩增", "⚠️ 考点/易错点：BS-seq检测DNA甲基化，ChIP-seq检测转录因子结合位点和组蛋白修饰；两者均需将读长比对到基因组，但实验原理不同。"], "code": "# BS-seq 流程 (DNA 甲基化)\nbismark_genome_preparation --path genome/\nbismark --genome genome/ -1 bs_r1.fq -2 bs_r2.fq\nbismark_methylation_extractor -s --comprehensive bs.bam\n# 未甲基化 C -> U -> T，甲基化 C 保持 C\n\n# ChIP-seq 流程\nbowtie2 -x genome_index -U chip.fq -S chip.sam\nsamtools sort -o chip.bam chip.sam\nmacs2 callpeak -t chip.bam -c input.bam -g hs -n chip_peak\n\n# 时间复杂度: 比对 O(N*M)，甲基化提取 O(N)", "lang": "Shell/Linux", "principle": "①解决什么问题/用途：本页介绍如何利用第二代测序技术（NGS）分析表观遗传修饰，重点包括DNA甲基化测序（BS-seq）和染色质免疫共沉淀测序（ChIP-seq），用于在全基因组水平检测DNA甲基化状态和蛋白质-DNA结合位点。\n②核心思想：BS-seq的核心思想是利用亚硫酸氢盐处理DNA，将未甲基化的胞嘧啶（C）转化为尿嘧啶（U），而甲基化的C保持不变，经PCR扩增后U变为胸腺嘧啶（T），通过测序和比对即可区分甲基化与未甲基化位点。通俗类比：就像给每个C贴上“已甲基化”或“未甲基化”的标签，未甲基化的C被“改写”成T，而甲基化的C保持原样，测序后就能读出哪些C被保护了。ChIP-seq则利用抗体特异性富集与目标蛋白结合的DNA片段，再通过测序定位结合位点。\n③主要步骤：BS-seq：基因组准备→亚硫酸氢盐处理→PCR扩增→测序→比对（bismark）→甲基化提取。ChIP-seq：蛋白质-DNA交联→超声波打断→抗体免疫沉淀→纯化DNA→连接接头→PCR扩增→测序→比对（bowtie）→峰检测。\n④复杂度或关键参数：BS-seq比对需考虑C→T转换，常用bismark等专用比对工具；ChIP-seq关键参数包括抗体特异性、超声片段大小、测序深度和峰检测阈值。\n⑤优缺点/适用场景：BS-seq可单碱基分辨率检测DNA甲基化，但会降低序列复杂度，比对难度大；ChIP-seq可全基因组定位蛋白结合位点，但依赖抗体质量，分辨率受片段大小限制。两者广泛用于表观遗传学、发育生物学和癌症研究。", "formula": [{"name": "亚硫酸氢盐转化规则", "expr": "C → U（未甲基化）；C → C（甲基化）", "note": "BS-seq中未甲基化胞嘧啶经亚硫酸氢盐处理脱氨变为尿嘧啶，PCR扩增后读为T；甲基化C保持不变读为C", "tex": "\\mathrm{C} \\rightarrow \\mathrm{U} \\quad (\\text{未甲基化});\\quad \\mathrm{C} \\rightarrow \\mathrm{C} \\quad (\\text{甲基化})"}, {"name": "甲基化率估计", "expr": "甲基化水平 = C_reads / (C_reads + T_reads)", "note": "C_reads为比对到该位点仍为C的读长数，T_reads为变为T的读长数", "tex": "\\text{甲基化水平} = \\frac{C_{\\text{reads}}}{C_{\\text{reads}} + T_{\\text{reads}}}"}], "check": {"q": "关于利用第二代测序分析表观遗传修饰，下列哪项说法正确？", "o": ["A. BS-seq流程中，DNA经亚硫酸氢盐处理后所有胞嘧啶都转化为尿嘧啶", "B. ChIP-seq流程用于检测DNA甲基化", "C. BS-seq流程中未甲基化的胞嘧啶C转化为尿嘧啶U，甲基化的C保持不变，用于检测DNA甲基化", "D. ChIP-seq不需要抗体免疫沉淀"], "a": "C", "e": "BS-seq流程：DNA经亚硫酸氢盐处理，未甲基化的胞嘧啶C转化为尿嘧啶U，甲基化的C保持不变，经PCR扩增后测序，再将读长比对到基因组，用于检测DNA甲基化。ChIP-seq流程：蛋白质与DNA结合，经超声波处理、抗体免疫沉淀、提纯DNA、连接接头、PCR扩增后测序，将读长比对到基因组，用于检测转录因子结合位点和组蛋白修饰。"}, "cards": [{"front": "BS-seq和ChIP-seq流程分别用于检测什么？", "back": "BS-seq用于检测DNA甲基化：DNA经亚硫酸氢盐处理，未甲基化的C转化为U，甲基化的C保持不变，经PCR扩增后测序，再将读长比对到基因组。ChIP-seq用于检测蛋白质-DNA结合：蛋白质与DNA结合，经超声波处理、抗体免疫沉淀、提纯DNA、连接接头、PCR扩增。", "mnemonic": "BS-seq测甲基化，ChIP-seq测蛋白结合", "useImg": false}]}, {"i": 15, "sec": "第四节 生物信息学在第二代测序中的应用", "title": "NGS功能基因组学综合应用与单细胞测序", "notes": "本页展示图14-10 NGS在功能基因组学中的综合应用（Werner, 2010）。该图显示DNA-Seq和RNA-Seq的初步分析：DNA-Seq包括reads、de novo组装、CNV、SNP、InDel等；RNA-Seq包括reads、新转录本/基因座、可变剪接位点、基因融合等。这些数据进一步用于数据库、通路、调控网络和网络重建，通过多重相关性、多重实验整合分析。随后介绍单细胞测序（single-cell sequencing, SCS）技术（图14-11），可在单细胞水平上检测基因组和转录组。George Daley等使用单细胞测序揭示了干细胞多能性的更多变化。单细胞组学在癌症和免疫治疗中具有重要意义：癌症细胞具有异质性，除患者间异质性外，同一肿瘤中也存在不同亚群，不同肿瘤细胞抗原表面排布也有异质性。", "page": 344, "level": "理解", "img": "assets/img/ch14/p344.jpg", "anim": null, "fig": "图14-10展示NGS在功能基因组学中的综合应用。看图时注意DNA-Seq和RNA-Seq的分析产出如何整合到数据库、通路和调控网络中。", "points": ["图14-10展示NGS在功能基因组学中的综合应用（Werner, 2010）", "DNA-Seq包括reads、de novo组装、CNV、SNP、InDel等", "RNA-Seq包括reads、新转录本/基因座、可变剪接位点、基因融合等", "这些数据进一步用于数据库、通路、调控网络和网络重建", "通过多重相关性、多重分析等整合", "⚠️ 考点/易错点：NGS功能基因组学综合应用：DNA-Seq分析CNV、SNP、InDel等，RNA-Seq分析新转录本、可变剪接、基因融合等；单细胞测序用于解析细胞异质性。"], "code": "# NGS 功能基因组学综合应用 (Python 伪代码)\n# DNA-Seq 分析\ndef dna_seq_analysis(reads):\n    contigs = de_novo_assemble(reads)      # de novo 组装\n    cnv = call_cnv(contigs)                # 拷贝数变异\n    snp = call_snp(contigs)                # SNP\n    indel = call_indel(contigs)            # InDel\n    return contigs, cnv, snp, indel\n\n# RNA-Seq 分析\ndef rna_seq_analysis(reads):\n    transcripts = assemble(reads)          # 新转录本/基因座\n    splicing = detect_splicing(reads)      # 可变剪接\n    fusion = detect_fusion(reads)          # 基因融合\n    return transcripts, splicing, fusion\n\n# 网络重建\nnetwork = integrate(dna_data, rna_data, pathway_db)\n# 时间复杂度: 组装 O(N log N)，网络重建 O(V*E)", "lang": "Python", "principle": "①解决什么问题/用途：本页展示NGS在功能基因组学中的综合应用框架（图14-10），涵盖DNA-Seq和RNA-Seq的初步分析及其向数据库、通路、调控网络和网络重建的整合，并引入单细胞测序技术。\n②核心思想：将DNA-Seq和RNA-Seq产生的海量reads经过组装、变异检测、表达定量等初步分析，得到CNV、SNP、InDel、新转录本、可变剪接、基因融合等信息，再通过多重相关性分析和多实验整合，构建调控网络和通路模型。通俗类比：就像把一堆散乱的拼图碎片（reads）先分类整理（初步分析），再拼成完整图案（网络重建），从而理解细胞的功能状态。单细胞测序则是在单个细胞水平上解析异质性。\n③主要步骤：DNA-Seq：reads→de novo组装→CNV/SNP/InDel检测；RNA-Seq：reads→新转录本/基因座→可变剪接→基因融合；整合分析：数据库注释→通路分析→调控网络重建→多重实验整合。单细胞测序：单细胞分离→文库构建→测序→表达矩阵分析。\n④复杂度或关键参数：de novo组装复杂度高，受reads长度和覆盖度影响；变异检测需考虑测序深度和错误率；单细胞测序关键参数包括细胞捕获效率、测序深度和批次效应。\n⑤优缺点/适用场景：综合应用可全面揭示基因组和转录组变异，但数据分析流程复杂，计算资源需求大；单细胞测序能解析细胞异质性，但存在技术噪声和 dropout 问题。适用于癌症研究、发育生物学和精准医学。", "formula": [], "check": {"q": "关于单细胞测序，下列哪项说法正确？", "o": ["A. 单细胞测序不能用于研究癌症内异质性", "B. 单细胞测序可对肿瘤循环细胞（CTC）、早期胚胎细胞等数量不足的细胞进行研究", "C. 单细胞测序只能研究基因表达水平，不能发现非编码RNA", "D. 单细胞测序已完全取代其他测序技术"], "a": "B", "e": "单细胞测序可帮助研究癌症内异质性，也可对肿瘤循环细胞（CTC）、早期胚胎细胞等数量不足的细胞进行研究。单细胞测序使基因表达水平的测量精度及对罕见非编码RNA的发现能力都得到提升，已成为研究热点。"}, "cards": [{"front": "图14-10中NGS在功能基因组学中的综合应用包括哪些初步分析？", "back": "DNA-Seq包括reads、de novo组装、CNV、SNP、InDel等；RNA-Seq包括reads、新转录本/基因座、可变剪接位点、基因融合等。这些数据进一步用于数据库、通路、调控网络和网络重建。", "mnemonic": "DNA-Seq和RNA-Seq分析整合到网络", "useImg": false}]}, {"i": 16, "sec": "第四节 生物信息学在第二代测序中的应用", "title": "单细胞测序应用与宏基因组学", "notes": "本页继续介绍单细胞测序的应用：在嵌合抗原受体T细胞（CAR-T）疗法中，经过CAR改造的T细胞识别和杀伤肿瘤抗原时产生的免疫反应有所不同。单细胞测序可帮助研究癌症内异质性，也可对肿瘤循环细胞（CTC）、早期胚胎细胞等数量不足的细胞进行研究。单细胞测序使基因表达水平的测量精度及对罕见非编码RNA的发现能力都得到提升，已成为研究热点，其临床应用被国家立为重点专项。细胞是执行生命活动的最小单位，单细胞组学的发展预示人类对生物机制的研究达到新高度。2016年启动的人类细胞图谱计划将对所有不同的人类细胞进行高度分类，收集细胞生理学、组织学、功能信息等多方面数据。图14-11展示单细胞测序流程（Nawy, 2014）：单细胞分离、逆转录、扩增cDNA、准备测序文库、测序。随后介绍宏基因组学（metagenomics）：以某一环境中全体微生物基因组为研究对象，利用生物信息学方法分析微生物群落的多样性、种群结构、功能活性和相互作用等关系。宏基因组最初应用于海洋、土壤等研究领域，现在也广泛应用于医学研究，如人类与共生体肠道菌群、感染性疾病等相互关系的研究。最初对环境中微生物群落的研究是根据保守的16S rRNA基因。", "page": 345, "level": "掌握", "img": "assets/img/ch14/p345.jpg", "anim": null, "fig": null, "points": ["单细胞测序在嵌合抗原受体T细胞（CAR-T）疗法中，经过CAR改造的T细胞识别和杀伤肿瘤抗原时产生的免疫反应有所不同", "单细胞测序可帮助研究癌症内异质性", "也可对肿瘤循环细胞（CTC）、早期胚胎细胞等数量不足的细胞进行研究", "单细胞测序使基因表达水平的测量精度及对罕见非编码RNA的发现能力都得到提升", "已成为研究热点，其临床应用被国家立为重点专项", "⚠️ 考点/易错点：单细胞测序的考点常落在其应用价值：可研究肿瘤内异质性、CTC和早期胚胎等稀有细胞，并提升基因表达精度与罕见非编码RNA发现能力；易错处是把它仅当作普通转录组测序，忽略其解决细胞异质性和微量样本问题的核心意义。"], "code": "# 单细胞测序分析 (Python / Scanpy)\nimport scanpy as sc\nadata = sc.read_10x_mtx('filtered_feature_bc_matrix/')\nsc.pp.filter_cells(adata, min_genes=200)\nsc.pp.normalize_total(adata, target_sum=1e4)\nsc.pp.log1p(adata)\nsc.pp.highly_variable_genes(adata, n_top_genes=2000)\nsc.tl.pca(adata)\nsc.pp.neighbors(adata)\nsc.tl.umap(adata)\nsc.tl.leiden(adata)\n# 应用: CAR-T 免疫反应、肿瘤异质性、CTC、早期胚胎\n# 时间复杂度: PCA O(N*D^2)，UMAP O(N log N)", "lang": "Python", "principle": "①解决什么问题/用途：本页继续介绍单细胞测序的应用，包括CAR-T疗法中T细胞免疫反应差异、癌症内异质性、循环肿瘤细胞（CTC）和早期胚胎细胞研究，并引入宏基因组学。\n②核心思想：单细胞测序通过分离单个细胞并对其转录组进行测序，揭示细胞间的基因表达差异，从而研究细胞异质性。通俗类比：就像把一杯混合果汁中的每一滴都单独品尝，而不是喝整杯混合汁，从而分辨出不同水果的味道。宏基因组学则直接对环境中所有微生物的DNA进行测序，无需分离培养。\n③主要步骤：单细胞测序：组织解离→单细胞捕获→逆转录和扩增→测序→数据分析（如Scanpy：过滤、归一化、log1p、高变基因选择、降维聚类）。宏基因组学：样本采集→DNA提取→测序→质量控制→去宿主→组装和注释。\n④复杂度或关键参数：单细胞测序关键参数包括min_genes（如200）、target_sum（如1e4）、高变基因数量等；宏基因组学关键参数包括测序深度、组装软件和数据库选择。\n⑤优缺点/适用场景：单细胞测序能发现罕见细胞类型和低表达非编码RNA，但成本高、通量有限；宏基因组学可研究不可培养微生物，但数据复杂、宿主污染难去除。适用于免疫学、肿瘤学和微生物组研究。", "formula": [], "check": {"q": "关于人类微生物组计划（HMP），下列哪项说法正确？", "o": ["A. HMP只研究人类胃肠道微生物", "B. HMP主要包括人类鼻腔、口腔、皮肤、胃肠道和泌尿生殖道的宏基因组样本数据和分析流程", "C. 2017年9月HMP进入第一阶段", "D. HMP不涉及微生物菌群结构与健康关系的研究"], "a": "B", "e": "人类微生物组计划（HMP）主要包括人类鼻腔、口腔、皮肤、胃肠道和泌尿生殖道的宏基因组样本数据和分析流程。2017年9月，HMP进入第二阶段，公开了对1631个新样本的宏基因组测序结果。HMP致力于研究与人体共生的微生物的菌群结构、分子过程与健康的关系。"}, "cards": [{"front": "单细胞测序有哪些应用？", "back": "在CAR-T疗法中研究免疫反应差异；研究癌症内异质性；对肿瘤循环细胞（CTC）、早期胚胎细胞等数量不足的细胞进行研究；提升基因表达水平测量精度及罕见非编码RNA发现能力。", "mnemonic": "CAR-T、癌症异质性、CTC、早期胚胎", "useImg": false}]}, {"i": 17, "sec": "第四节 生物信息学在第二代测序中的应用", "title": "人类微生物组计划、细胞微环境与三维基因组学", "notes": "本页介绍人类微生物组计划（HMP，http://www.hmpdacc.org/），主要包括人类鼻腔、口腔、皮肤、胃肠道和泌尿生殖道的宏基因组样本数据和分析流程。2017年9月，HMP进入第二阶段，公开了对1631个新样本的宏基因组测序结果。HMP致力于研究与人体共生的微生物的菌群结构、分子过程与健康的关系。2016年美国国家微生物组计划将视野拓展到人类之外的生态系统。细胞的活动不仅取决于自身基因组特征，也受周围同类细胞、基质细胞、细胞间质、细胞外基质等因素影响，这些因素统称为细胞微环境（microenvironment）。近年来以癌症细胞为典型的基因组学研究已开始考虑细胞微环境的影响。随后介绍三维基因组学：人类基因组计划完成代表了解序列的第一阶段；ENCODE计划完成标志着对各种基因组元件的了解；然而细胞内部染色体复杂的三维结构使得各功能元件、游离RNA分子和蛋白质复合物之间的相互作用异常复杂。以Hi-C技术为代表的空间构象捕获技术的发展，推动了基因组学的第三次浪潮，即三维基因组学。早期基因组学研究往往从线性角度分析基因组，一维距离上相距很远的两个基因可能会有很频繁的互作，这是因为DNA与蛋白质高度浓缩折叠成染色质，这种折叠结构在调控过程中扮演重要角色。", "page": 346, "level": "理解", "img": "assets/img/ch14/p346.jpg", "anim": null, "fig": null, "points": ["人类微生物组计划（HMP，http://www.hmpdacc.org/），主要包括人类鼻腔、口腔、皮肤、胃肠道和泌尿生殖道的宏基因组样本数据和分析流程", "2017年9月，HMP进入第二阶段，公开了对1631个新样本的宏基因组测序结果", "HMP致力于研究与人体共生的微生物的菌群结构、分子过程与健康的关系", "2016年美国国家微生物组计划将视野拓展到人类之外", "⚠️ 考点/易错点：人类微生物组计划（HMP）的易考点是研究对象和阶段进展：主要覆盖鼻腔、口腔、皮肤、胃肠道和泌尿生殖道等人体共生微生物宏基因组，2017年第二阶段公开1631个新样本；易混处是HMP与2016年美国国家微生物组计划的范围不同，后者拓展到人类之外生态系统。"], "code": "# HMP 宏基因组分析流程 (Linux 命令)\n# 下载数据\nwget http://www.hmpdacc.org/data/...\n# 质量控制\nfastqc sample.fq\ntrimmomatic PE sample_1.fq sample_2.fq out_1.fq out_2.fq\n# 去宿主\nbowtie2 -x human_genome -1 out_1.fq -2 out_2.fq --un nonhuman.fq\n# 物种注释\nkraken2 --db minikraken nonhuman.fq --output kraken.out\n# 功能注释\nhumann2 --input nonhuman.fq --output humann2_out\n# 三维基因组学 (Hi-C)\nhicup --index genome_index --digest genome_digest reads.fq\n# 时间复杂度: 比对 O(N*M)，Kraken O(N)", "lang": "Shell/Linux", "principle": "①解决什么问题/用途：本页介绍人类微生物组计划（HMP）及其宏基因组分析流程，并提及细胞微环境与三维基因组学。HMP旨在研究人体共生微生物的菌群结构、分子过程与健康的关系。\n②核心思想：通过对人体不同部位（鼻腔、口腔、皮肤、胃肠道、泌尿生殖道）的宏基因组样本进行测序和分析，揭示微生物群落的组成和功能。通俗类比：就像调查一个城市中所有居民的职业和活动，而不是只研究某一个人，从而了解整个社区的运作。三维基因组学则研究染色质在空间上的折叠和相互作用。\n③主要步骤：HMP流程：下载数据→质量控制（fastqc、trimmomatic）→去宿主（bowtie2）→非宿主序列组装和注释→菌群结构和功能分析。三维基因组学常用Hi-C等技术。\n④复杂度或关键参数：宏基因组分析关键参数包括测序深度、去宿主效率、组装软件和数据库；HMP第二阶段公开了1631个新样本的测序结果。\n⑤优缺点/适用场景：HMP提供了大规模人体微生物组参考数据，但样本间差异大、宿主污染和低丰度物种检测仍是挑战。适用于微生物组与健康、疾病关联研究。", "formula": [], "check": {"q": "关于4D核体计划与Hi-C技术，下列哪项说法正确？", "o": ["A. 4D核体计划旨在定义细胞核结构与基因组组织的术语和数据类型规范", "B. Hi-C技术流程中不需要甲醛交联", "C. Hi-C技术流程中不需要生物素标记", "D. 4D核体计划只包括图谱绘制一个部分"], "a": "A", "e": "4D核体计划旨在定义细胞核结构与基因组组织的术语和数据类型规范，建立细胞核的全面综合模型，探索核结构形成原理及其对生命活动的影响。Hi-C技术流程：先用甲醛交联并分离染色质，再酶切并用生物素标记，连接DNA并纯化，移除末端生物素并片段化，最后用生物素拉下片段并进行高通量测序。4D核体计划包括图谱绘制等三个部分。"}, "cards": [{"front": "人类微生物组计划（HMP）主要包括哪些部位？", "back": "人类鼻腔、口腔、皮肤、胃肠道和泌尿生殖道的宏基因组样本数据和分析流程。", "mnemonic": "鼻腔、口腔、皮肤、胃肠道、泌尿生殖道", "useImg": false}]}, {"i": 18, "sec": "第五节 生物信息学新技术与发展趋势", "title": "4D核体计划与Hi-C技术流程", "notes": "本页属于‘第五节 生物信息学新技术与发展趋势’，重点介绍4D核体计划及Hi-C技术。4D核体计划旨在定义细胞核结构与基因组组织的术语和数据类型规范，建立细胞核的全面综合模型，探索核结构形成原理及其对生命活动的影响。图示图14-12展示Hi-C技术流程：先用甲醛交联并分离染色质，再酶切并用生物素标记，连接DNA并纯化，移除末端生物素并片段化，最后用生物素拉下片段并进行高通量测序。图14-13展示4D核体计划的三个部分：图谱绘制（联结及动态的分子遗传学图谱）、模型建立（约束模型和分子遗传学模型）、功能验证（遗传学和生物物理验证）。该计划体现生物学研究目标动态化，结合3D基因组精准研究，用时间序列数据推断基因组动态改变，目标是构建细胞核的4D模型。", "page": 347, "level": "理解", "img": "assets/img/ch14/p347.jpg", "anim": null, "fig": "图14-12展示Hi-C技术流程。看图时注意从交联、酶切、标记、连接、纯化到片段化的步骤，理解Hi-C用于研究三维基因组结构。", "points": ["4D核体计划旨在定义细胞核结构与基因组组织的术语和数据类型规范", "建立细胞核的全面综合模型，探索核结构形成原理及其对生命活动的影响", "图14-12展示Hi-C技术流程：先用甲醛交联并分离染色质，再酶切并用生物素标记", "连接DNA并纯化，移除末端生物素并片段化，最后用生物素拉下片段", "⚠️ 考点/易错点：Hi-C技术流程是高频考点，顺序易错：甲醛交联并分离染色质→酶切并生物素标记→连接DNA并纯化→移除末端生物素并片段化→生物素拉下片段并高通量测序；同时要区分4D核体计划的目标是定义核结构与基因组组织规范、建立综合模型，而非单纯测序技术。"], "code": "# Hi-C 数据处理核心步骤（Python 风格伪代码）\n# 输入: paired-end reads (R1.fq, R2.fq), reference genome\n# 输出: contact matrix\n\ndef hic_pipeline(r1, r2, genome):\n    # 1. 比对：将双端 reads 比对到参考基因组\n    alignments = bowtie2(r1, r2, genome)   # O(N * L), N=reads数, L=读长\n\n    # 2. 过滤：去除未比对、多比对、PCR 重复\n    valid_pairs = filter_pairs(alignments)  # O(N)\n\n    # 3. 酶切位点附近重新定位（5' 端）\n    pairs = re_align_to_restriction_sites(valid_pairs)  # O(N)\n\n    # 4. 按基因组 bin 划分（如 1Mb / 100kb / 10kb）\n    bins = assign_bins(pairs, bin_size=1_000_000)  # O(N)\n\n    # 5. 构建接触矩阵\n    matrix = build_contact_matrix(bins)  # O(N + B^2), B=bin数\n\n    # 6. 归一化（ICE / KR）\n    matrix_norm = ice_normalize(matrix)  # O(B^3) 迭代\n    return matrix_norm\n\n# 极简示例：3 个 bin 的接触矩阵\n# bin1-bin1: 10, bin1-bin2: 3, bin1-bin3: 1\n# bin2-bin2: 8,  bin2-bin3: 2\n# bin3-bin3: 5\n# matrix = [[10,3,1],[3,8,2],[1,2,5]]\n\n# 时间复杂度总览：\n# 比对 O(N*L)，过滤 O(N)，分箱 O(N)，矩阵 O(N+B^2)，归一化 O(B^3)", "lang": "Python", "principle": "①解决什么问题/用途：本页介绍4D核体计划和Hi-C技术流程。4D核体计划旨在定义细胞核结构与基因组组织的术语和数据类型规范，建立细胞核的全面综合模型；Hi-C用于检测染色质三维空间相互作用。\n②核心思想：Hi-C通过甲醛交联固定染色质空间构象，酶切后连接空间上邻近的DNA片段，再通过高通量测序检测连接产物，从而推断染色质的三维接触频率。通俗类比：就像把一团毛线先固定、剪断、再重新连接，然后通过分析哪些线头连在一起，推断毛线原来的缠绕方式。\n③主要步骤：甲醛交联→分离染色质→酶切→生物素标记→连接DNA→纯化→移除末端生物素→片段化→生物素拉下→高通量测序→比对→构建接触矩阵。\n④复杂度或关键参数：Hi-C数据处理包括比对（bowtie2）、过滤、接触矩阵构建和归一化；关键参数包括酶切效率、测序深度和分辨率。\n⑤优缺点/适用场景：Hi-C可全基因组检测染色质相互作用，分辨率可达kb级，但数据量大、分析复杂；适用于三维基因组学、基因组组装和宏基因组物种聚类。", "formula": [], "check": {"q": "关于新技术相互关系与生物信息学挑战，下列哪项说法正确？", "o": ["A. 第三代单分子测序不能免去单细胞测序中的扩增步骤", "B. 单细胞测序不能辅助宏基因组测序", "C. Hi-C技术可帮助宏基因组测序中不同微生物基因组的组装", "D. 高通量测序不带来数据存储管理挑战"], "a": "C", "e": "第三代单分子测序可免去单细胞测序中的扩增步骤，提高测序精确性；单细胞测序可辅助宏基因组测序，如新细菌Candidatus kryptonia的发现；Hi-C技术可帮助宏基因组测序中不同微生物基因组的组装。高通量测序带来数据存储管理、比较分析、可视化等挑战。"}, "cards": [{"front": "Hi-C技术流程的主要步骤是什么？", "back": "先用甲醛交联并分离染色质，再酶切并用生物素标记，连接DNA并纯化，移除末端生物素并片段化，最后用生物素拉下片段。", "mnemonic": "交联→酶切→标记→连接→纯化→片段化→拉下", "useImg": false}]}, {"i": 19, "sec": "第五节 生物信息学新技术与发展趋势", "title": "新技术相互关系与生物信息学挑战", "notes": "本页总结新技术之间的相互关系及生物信息学挑战。第三代单分子测序可免去单细胞测序中的扩增步骤，提高测序精确性；单细胞测序可辅助宏基因组测序，如新细菌Candidatus kryptonia的发现；Hi-C技术可帮助宏基因组测序中不同微生物基因组的组装。实验方法日益强大，计算方法也快速发展。高通量测序带来数据存储管理、比较分析、可视化等挑战：原始图像数据量大，难以长期保存，可舍弃；序列数据需长期持有。基因组比对需新算法，要求更准确快速、灵活、硬件要求低、容错。多倍体、高重复序列物种全基因组测序拼接难度大。数据质量控制、数千个富集区域可视化也是挑战。页末列出复习题，涉及第二代测序技术异同、优势、常见平台、Roche 454和Illumina Genome Analyzer测序原理等。", "page": 348, "level": "掌握", "img": "assets/img/ch14/p348.jpg", "anim": null, "fig": null, "points": ["第三代单分子测序可免去单细胞测序中的扩增步骤，提高测序精确性", "单细胞测序可辅助宏基因组测序，如新细菌Candidatus kryptonia的发现", "Hi-C技术可帮助宏基因组测序中不同微生物基因组的组装", "实验方法日益强大，计算方法也快速发展", "高通量测序带来数据存储管理、比较分析、可视化等挑战：原始图像数据量大，难处理", "⚠️ 考点/易错点：本页最易考新技术之间的互补关系：第三代单分子测序可免扩增提高单细胞测序精确性，单细胞测序可辅助宏基因组测序发现新细菌，Hi-C可帮助宏基因组中不同微生物基因组组装；易错点是忽略高通量测序带来的数据存储、比较分析、可视化等生物信息学挑战，以及原始图像数据可舍弃而序列数据需长期保存的区别。"], "code": "# 新技术相互关系与生物信息学挑战（Python 示意）\n\n# 1. 第三代单分子测序免扩增，提高单细胞测序精度\n# 2. 单细胞测序辅助宏基因组：发现 Candidatus kryptonia\n# 3. Hi-C 辅助宏基因组组装：将 contigs 按物种聚类\n\n# 示例：用 Hi-C 接触信号对宏基因组 contigs 聚类\nimport numpy as np\nfrom sklearn.cluster import SpectralClustering\n\ndef cluster_contigs_by_hic(contact_matrix, n_clusters):\n    \"\"\"\n    contact_matrix: contig 间 Hi-C 接触矩阵 (C x C)\n    n_clusters: 预期物种数\n    返回: 每个 contig 的物种标签\n    \"\"\"\n    # 归一化\n    norm = contact_matrix / contact_matrix.sum(axis=1, keepdims=True)\n    # 谱聚类\n    sc = SpectralClustering(n_clusters=n_clusters, affinity='precomputed')\n    labels = sc.fit_predict(norm)\n    return labels\n\n# 时间复杂度：谱聚类 O(C^3)，C=contig 数\n\n# 数据存储挑战：\n# - 原始图像数据：可舍弃，节省 PB 级存储\n# - 序列数据：需长期保存，建议压缩（CRAM / zstd）\n# Linux 示例：\n# samtools view -C -T ref.fa input.bam > output.cram\n# zstd -19 reads.fastq -o reads.fastq.zst", "lang": "Python", "principle": "①解决什么问题/用途：本页总结新技术之间的相互关系及生物信息学挑战，包括第三代单分子测序、单细胞测序、宏基因组测序和Hi-C技术的相互辅助，以及高通量测序带来的数据存储、比较分析和可视化挑战。\n②核心思想：不同技术可以互补：第三代单分子测序免扩增提高单细胞测序精度；单细胞测序辅助宏基因组发现新细菌；Hi-C辅助宏基因组组装，将contigs按物种聚类。通俗类比：就像不同工具协同工作，望远镜看远，显微镜看细，结合起来能更全面理解世界。\n③主要步骤：以Hi-C辅助宏基因组组装为例：获取Hi-C接触信号→计算contigs间接触频率→构建相似性矩阵→谱聚类（如SpectralClustering）→将contigs按物种分组。\n④复杂度或关键参数：Hi-C辅助组装关键参数包括接触矩阵的归一化、聚类算法和簇数；数据存储挑战包括原始图像数据可舍弃，序列数据需长期保存。\n⑤优缺点/适用场景：多技术整合能提高组装和发现能力，但计算复杂、数据管理困难；适用于复杂微生物组、单细胞基因组和三维基因组研究。", "formula": [], "check": {"q": "第十四章参考文献中，Mardis ER于2008年发表的文献主题是什么？", "o": ["A. RNA-Seq分析的进展", "B. 下一代DNA测序方法及其对遗传学的影响", "C. 人类微生物组研究框架", "D. 新测序技术在转录组分析中的应用"], "a": "B", "e": "参考文献列表中，Mardis ER 2008年发表的是关于下一代DNA测序方法及其对遗传学影响的文献。Haas BJ和Zody MC 2010年发表RNA-Seq分析的进展；Methée BA等2012年发表人类微生物组研究框架；Morozova O等2009年发表新测序技术在转录组分析中的应用。"}, "cards": [{"front": "高通量测序带来的生物信息学挑战有哪些？", "back": "数据存储管理、比较分析、可视化等挑战：原始图像数据量大，难处理。", "mnemonic": "存储、比较、可视化", "useImg": false}]}, {"i": 20, "sec": "第五节 生物信息学新技术与发展趋势", "title": "参考文献", "notes": "本页为第十四章参考文献列表，列出与新一代测序技术及其应用相关的文献，包括Haas BJ和Zody MC 2010年关于RNA-Seq分析的进展、Horner DS等2010年关于下一代测序的基因组学和后基因组学应用生物信息学方法、Mardis ER 2008年关于下一代DNA测序方法及其对遗传学影响、Methée BA等2012年人类微生物组研究框架、Morozova O等2009年新测序技术在转录组分析中的应用等。这些文献为本章内容提供学术支撑，涉及RNA-Seq分析、测序方法、微生物组、转录组分析等方向。学习时可作为扩展阅读，了解新一代测序技术的应用背景和发展趋势。", "page": 349, "level": "了解", "img": "assets/img/ch14/p349.jpg", "anim": null, "fig": null, "points": ["第十四章参考文献列表", "列出与新一代测序技术及其应用相关的文献", "包括Haas BJ和Zody MC 2010年关于RNA-Seq分析的进展", "Horner DS等2010年关于下一代测序的基因组学和后基因组学应用生物信息学方法", "Mardis ER 2008年关于下一代DNA测序方法及其对遗传学影响等", "⚠️ 考点/易错点：该页为参考文献页，通常不考具体文献内容；若考，最多是识别本章相关文献主题，如RNA-Seq分析、下一代测序的基因组学与后基因组学应用、下一代DNA测序方法、人类微生物组研究框架、新测序技术用于转录组分析等，易错点是把它误当作正文技术细节记忆。"], "code": "", "lang": null, "principle": null, "formula": null, "check": {"q": "关于文档生成信息页，下列哪项说法正确？", "o": ["A. 该页包含重要的生物信息学专业知识", "B. 该页为Anna's Archive生成的文档信息页，包含PDF附件统计信息，非教材正文内容", "C. 该页是第十四章的核心内容", "D. 学习时必须仔细研究该页的技术细节"], "a": "B", "e": "该页为Anna's Archive生成的文档信息页，包含PDF附件中的统计信息，如文件名、文件大小、MD5、SHA1、SHA256、CRC32、解压后大小、页数等。该页非教材正文内容，属于扫描版电子书的元数据页，学习时无需关注具体技术细节。"}, "cards": [{"front": "第十四章参考文献中包括哪些关于RNA-Seq分析的文献？", "back": "Haas BJ和Zody MC 2010年关于RNA-Seq分析的进展。", "mnemonic": "Haas & Zody 2010", "useImg": false}]}, {"i": 21, "sec": "第五节 生物信息学新技术与发展趋势", "title": "文档生成信息", "notes": "本页为Anna’s Archive生成的文档信息页，包含PDF附件中的统计信息，如文件名、文件大小、MD5、SHA1、SHA256、CRC32、解压后大小、页数等。该页非教材正文内容，属于扫描版电子书的元数据页。学习时无需关注具体技术细节，仅需了解该页为文档来源和统计信息，不涉及生物信息学专业知识。若用于自学，可跳过此页，直接关注前几页的4D核体计划、Hi-C技术流程、新技术相互关系及生物信息学挑战等内容。", "page": 350, "level": "了解", "img": "assets/img/ch14/p350.jpg", "anim": null, "fig": null, "points": ["Anna’s Archive生成的文档信息页", "包含PDF附件中的统计信息，如文件名、文件大小、MD5、SHA1、SHA256、CRC32、解压后大小、页数等", "该页非教材正文内容，属于扫描版电子书的元数据页", "学习时无需关注具体技术细节，仅需了解该页为文档来源和统计信息", "若用于自学，可跳过此页", "⚠️ 考点/易错点：该页为Anna’s Archive生成的文档元数据页，不属于《生物信息学》教材正文，通常不设考点；易错点是误把文件名、MD5、SHA1、SHA256、CRC32、页数等统计信息当作生物信息学专业知识。学习时应跳过此页，重点看前几页的4D核体计划、Hi-C流程及新技术相互关系。"], "code": "", "lang": null, "principle": null, "formula": null, "check": null, "cards": [{"front": "第350页的主要内容是什么？", "back": "Anna’s Archive生成的文档信息页，包含PDF附件中的统计信息，如文件名、文件大小、MD5、SHA1、SHA256、CRC32、解压后大小、页数等。非教材正文内容。", "mnemonic": "文档元数据页，可跳过", "useImg": false}]}], "mcq": [{"id": "ch14_mcq_1", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "下列关于Sanger测序的描述，正确的是：", "o": ["A. 它属于第二代测序技术，主要特点是高通量短读长", "B. 它利用ddNTP终止DNA链延伸，准确率高但通量低", "C. 它完全不需要电泳分离即可读取碱基序列", "D. 它主要依赖桥式PCR进行信号放大"], "a": "B", "e": "Sanger测序属于第一代测序，核心是双脱氧终止法，利用ddNTP终止延伸，通过电泳分离荧光标记片段。其准确率高、读长长，但通量低、成本高。桥式PCR是Illumina二代测序的扩增方式。", "kp": "ch14_s0_0"}, {"id": "ch14_mcq_2", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "Roche 454测序平台的核心测序原理是：", "o": ["A. 桥式PCR结合可逆终止子合成测序", "B. 大规模并行焦磷酸合成测序", "C. 基于磁珠的克隆连接DNA测序", "D. 纳米孔单分子测序"], "a": "B", "e": "Roche/454采用大规模并行焦磷酸合成测序。dNTP掺入释放焦磷酸，经APS生成ATP，荧光素酶催化发光。Illumina采用桥式PCR和可逆终止子，SOLiD采用连接测序，纳米孔属于三代测序。", "kp": "ch14_s0_2"}, {"id": "ch14_mcq_3", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "Illumina Solexa测序中，桥式PCR的主要作用是：", "o": ["A. 将RNA直接转化为蛋白质", "B. 在固相表面扩增DNA片段形成克隆簇", "C. 将甲基化胞嘧啶转化为尿嘧啶", "D. 利用连接酶读取双碱基编码"], "a": "B", "e": "Illumina平台通过桥式PCR在固相表面扩增DNA片段，形成空间分离的克隆簇，再进行合成测序。RNA直接转蛋白质不是测序步骤；重硫酸盐处理用于甲基化研究；连接酶和双碱基编码属于SOLiD。", "kp": "ch14_s0_4"}, {"id": "ch14_mcq_4", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "ABI SOLiD测序中“双碱基编码”的主要优点是：", "o": ["A. 使读长达到1000 bp以上", "B. 每个碱基被判读两次，降低原始数据错误", "C. 完全不需要参考基因组即可组装", "D. 可直接测RNA而不需反转录"], "a": "B", "e": "SOLiD采用双碱基编码，每个碱基被判读两次，因此可减少原始数据错误，准确度较高。其读长较短，约35 bp，仍需建库和测序，不能直接测RNA。", "kp": "ch14_s0_5"}, {"id": "ch14_mcq_5", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "全基因组重测序（re-sequencing）通常用于：", "o": ["A. 对未知基因组物种进行从头组装", "B. 对已有参考基因组的个体进行差异分析", "C. 只检测DNA甲基化水平", "D. 只定量小非编码RNA表达"], "a": "B", "e": "全基因组重测序是对已知参考基因组的物种进行不同个体测序，通过比对发现SNP、InDel和结构变异等。从头组装适用于无参考基因组；甲基化和小RNA分析分别属于表观组学和smRNA-seq。", "kp": "ch14_s0_8"}, {"id": "ch14_mcq_6", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "RNA-seq通常测序的对象是：", "o": ["A. 直接测序原始RNA分子", "B. 反转录得到的cDNA文库", "C. 只测序蛋白质", "D. 只测序甲基化DNA"], "a": "B", "e": "RNA-seq通常先将mRNA分离并反转录为cDNA，构建cDNA文库后测序，从而推断RNA信息。它不是直接测RNA，也不是测蛋白质或甲基化DNA。", "kp": "ch14_s0_8"}, {"id": "ch14_mcq_7", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "关于ChIP-seq，下列描述正确的是：", "o": ["A. 用于研究蛋白质与DNA的结合位点", "B. 用于检测SNP和InDel", "C. 用于测定宏基因组物种多样性", "D. 用于单细胞全基因组扩增"], "a": "A", "e": "ChIP-seq即染色质免疫共沉淀测序，通过抗体富集与蛋白质结合的DNA片段，再测序定位结合位点或组蛋白修饰区域。SNP/InDel检测常由重测序完成；宏基因组和单细胞测序是其他方向。", "kp": "ch14_s0_8"}, {"id": "ch14_mcq_8", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "重硫酸盐测序（bisulfite sequencing）的原理是：", "o": ["A. 甲基化胞嘧啶转化为尿嘧啶，未甲基化胞嘧啶不变", "B. 未甲基化胞嘧啶转化为尿嘧啶，甲基化胞嘧啶不变", "C. 所有胞嘧啶都转化为腺嘌呤", "D. 所有鸟嘌呤都转化为胸腺嘧啶"], "a": "B", "e": "重硫酸盐处理使未甲基化胞嘧啶转化为尿嘧啶，而甲基化胞嘧啶保持不变，从而区分甲基化状态。5hmC也会抵抗转化，需用oxBS-seq、TAB-seq等方法进一步区分。", "kp": "ch14_s0_4"}, {"id": "ch14_mcq_9", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "在NGS差异表达分析中，单因素两组数据常用的统计方法是：", "o": ["A. t检验", "B. two-way ANOVA", "C. 隐马尔可夫模型", "D. 纳米孔测序"], "a": "A", "e": "单因素两组数据常用t检验，计算P值并筛选显著差异基因。单因素多组用one-way ANOVA，多因素用two-way ANOVA。隐马尔可夫模型属于机器学习/序列分析方法，纳米孔测序是测序技术。", "kp": "ch14_s0_10"}, {"id": "ch14_mcq_10", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "关于宏基因组学，下列描述正确的是：", "o": ["A. 只研究可纯培养的微生物", "B. 以某一环境中全体微生物基因组为研究对象", "C. 只能基于16S rRNA，不能进行全基因组测序", "D. 主要用于单细胞转录组分析"], "a": "B", "e": "宏基因组学以环境中全体微生物基因组为研究对象，可分析群落多样性、结构和功能。它突破了传统纯培养限制，最初常用16S rRNA，后来可发展到全基因组测序分析。单细胞转录组属于单细胞组学。", "kp": "ch14_s0_16"}, {"id": "ch14_mcq_11", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "在Roche 454测序中，焦磷酸测序法通过检测哪种物质的释放来间接测定DNA序列？", "o": ["A. 荧光标记的dNTP", "B. 焦磷酸", "C. ATP", "D. 荧光素"], "a": "B", "e": "Roche 454测序原理是：DNA聚合酶催化dNTP加入DNA链时释放焦磷酸，焦磷酸与APS结合生成ATP，ATP驱动荧光素酶催化荧光素氧化发光。因此直接检测的是焦磷酸释放，但最终读出的是荧光信号。", "kp": "ch14_s0_2"}, {"id": "ch14_mcq_12", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "Illumina/Solexa测序中，桥式PCR的主要作用是？", "o": ["A. 将DNA片段打断成300-800bp", "B. 在flow cell上形成密集的DNA簇", "C. 将甲基化胞嘧啶转化为尿嘧啶", "D. 连接荧光标记的8bp探针"], "a": "B", "e": "Illumina测序中，单链DNA片段与flow cell上的引物杂交，经桥式扩增形成局部密集的簇，从而提供足够的信号强度用于边合成边测序。", "kp": "ch14_s0_4"}, {"id": "ch14_mcq_13", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "SOLiD测序采用连接酶进行测序，其探针的荧光颜色由哪几个碱基决定？", "o": ["A. 第1、2位碱基", "B. 第3、4位碱基", "C. 第5、6位碱基", "D. 第7、8位碱基"], "a": "A", "e": "SOLiD探针为8bp，其中第1、2位碱基构成编码区，决定探针的荧光颜色；第3-5位为随机碱基，第6-8位为可与任何碱基配对的特殊碱基。", "kp": "ch14_s0_6"}, {"id": "ch14_mcq_14", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "在RNA-seq分析中，有参考基因组策略的两种主要流程是？", "o": ["A. 先匹配再组装、先组装再匹配", "B. 先注释再组装、先组装再注释", "C. 先聚类再匹配、先匹配再聚类", "D. 先定量再组装、先组装再定量"], "a": "A", "e": "有参考基因组RNA-seq分析策略包括“先匹配再组装”（reads先比对到参考基因组，再合并为转录本）和“先组装再匹配”（reads先组装成转录本，再比对到基因组）。", "kp": "ch14_s0_13"}, {"id": "ch14_mcq_15", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "在重硫酸盐测序（BS-seq）中，未甲基化的胞嘧啶经重硫酸盐处理后转变为？", "o": ["A. 胸腺嘧啶", "B. 尿嘧啶", "C. 腺嘌呤", "D. 鸟嘌呤"], "a": "B", "e": "重硫酸盐处理使未甲基化的胞嘧啶脱氨基转变为尿嘧啶，而甲基化的胞嘧啶保持不变。PCR扩增后尿嘧啶被读作胸腺嘧啶，从而区分甲基化状态。", "kp": "ch14_s0_9"}, {"id": "ch14_mcq_16", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "以下哪个工具主要用于NGS短序列的重新组装拼接？", "o": ["A. MOSAIK", "B. RMAP", "C. Velvet", "D. SOAP"], "a": "C", "e": "Velvet是用于短片段序列重新组装拼接的工具；MOSAIK和RMAP用于序列匹配；SOAP也用于短序列匹配到参考基因组。", "kp": "ch14_s0_11"}], "judge": [{"id": "ch14_judge_1", "modI": 0, "q": "Sanger测序是第一代测序的代表，其读长可达约1000 bp，单碱基准确率可达99.999%。", "a": "对", "e": "Sanger测序又称双脱氧终止法，读长长、准确率高，是人类基因组计划主要依赖的技术。", "kp": "ch14_s0_0"}, {"id": "ch14_judge_2", "modI": 0, "q": "第二代测序多数仍依赖PCR扩增，而三代测序强调单分子、无需扩增。", "a": "对", "e": "二代测序通过乳液PCR或桥式PCR等方式生成克隆阵列；三代测序强调单分子读取，无需PCR扩增。", "kp": "ch14_s0_1"}, {"id": "ch14_judge_3", "modI": 0, "q": "Roche 454焦磷酸测序的主要错误类型为替换（Substitution），尤其在同聚物区域容易产生误差。", "a": "错", "e": "Roche 454的主要错误类型为插入缺失（Indel），尤其在同聚物区域容易产生误差；替换为主是Illumina等平台的错误特征。", "kp": "ch14_s0_2"}, {"id": "ch14_judge_4", "modI": 0, "q": "Illumina/Solexa平台采用桥式PCR在固相表面扩增DNA片段，形成克隆簇。", "a": "对", "e": "Illumina/Solexa平台采用桥式PCR，测序时使用可逆终止子标记的dNTP，每轮只掺入一个碱基。", "kp": "ch14_s0_4"}, {"id": "ch14_judge_5", "modI": 0, "q": "ABI SOLiD平台使用DNA聚合酶进行测序，原始数据由四种颜色编码组成。", "a": "错", "e": "ABI SOLiD平台使用连接酶而非DNA聚合酶进行测序，原始数据由四种颜色编码组成。", "kp": "ch14_s0_6"}, {"id": "ch14_judge_6", "modI": 0, "q": "RNA-seq通常直接测RNA，而不是测cDNA。", "a": "错", "e": "RNA-seq通常先将mRNA分离并反转录为cDNA，构建片段化cDNA文库后进行高通量测序，因此测的是cDNA。", "kp": "ch14_s0_12"}, {"id": "ch14_judge_7", "modI": 0, "q": "重硫酸盐测序中，未甲基化胞嘧啶转化为尿嘧啶，甲基化胞嘧啶不变。", "a": "对", "e": "这是重硫酸盐测序的经典原理，用于研究DNA甲基化。", "kp": "ch14_s0_9"}, {"id": "ch14_judge_8", "modI": 0, "q": "ChIP-seq通过抗体特异性富集与蛋白质结合的DNA片段，再高通量测序，用于定位转录因子结合位点或组蛋白修饰区域。", "a": "对", "e": "ChIP-seq是表观组学测序的重要方法之一。", "kp": "ch14_s0_8"}, {"id": "ch14_judge_9", "modI": 0, "q": "单细胞测序结果反映细胞群体平均信号，可能掩盖细胞异质性。", "a": "错", "e": "传统测序通常使用大量混合细胞，结果反映细胞群体平均信号，可能掩盖细胞异质性；单细胞测序可在单细胞水平检测基因组和转录组，揭示细胞异质性。", "kp": "ch14_s0_15"}, {"id": "ch14_judge_10", "modI": 0, "q": "宏基因组学以某一环境中全体微生物基因组为研究对象，突破了传统微生物研究依赖纯培养的瓶颈。", "a": "对", "e": "自然界约99%微生物不可培养，宏基因组学利用生物信息学分析微生物群落的多样性、种群结构、功能活性和相互作用。", "kp": "ch14_s0_16"}], "fill": [{"id": "ch14_fill_1", "modI": 0, "q": "Sanger测序又称________，其核心是利用________终止DNA链延伸。", "a": "双脱氧终止法,ddNTP", "kp": "ch14_s0_0"}, {"id": "ch14_fill_2", "modI": 0, "q": "第二代测序以________、________为特征，代表平台包括Roche 454、Illumina Solexa、ABI SOLiD等。", "a": "高通量,短读长", "kp": "ch14_s0_4"}, {"id": "ch14_fill_3", "modI": 0, "q": "Roche 454焦磷酸测序中，DNA聚合酶催化dNTP掺入时释放________；焦磷酸与APS结合生成________；荧光素酶催化荧光素氧化并发出荧光。", "a": "焦磷酸,ATP", "kp": "ch14_s0_2"}, {"id": "ch14_fill_4", "modI": 0, "q": "Illumina/Solexa平台采用________在固相表面扩增DNA片段，形成克隆簇；测序时使用可逆终止子标记的dNTP，每轮只掺入________个碱基。", "a": "桥式PCR,一", "kp": "ch14_s0_4"}, {"id": "ch14_fill_5", "modI": 0, "q": "ABI SOLiD平台采用________策略，每个碱基被判读________次，因此可降低原始数据错误。", "a": "双碱基编码,两", "kp": "ch14_s0_7"}, {"id": "ch14_fill_6", "modI": 0, "q": "RNA-seq通常先将mRNA分离并反转录为________，构建片段化cDNA文库后进行高通量测序，因此RNA-seq不是直接测RNA，而是测________。", "a": "cDNA,cDNA", "kp": "ch14_s0_8"}, {"id": "ch14_fill_7", "modI": 0, "q": "重硫酸盐测序中，未甲基化胞嘧啶转化为________，甲基化胞嘧啶________。", "a": "尿嘧啶,不变", "kp": "ch14_s0_9"}, {"id": "ch14_fill_8", "modI": 0, "q": "NCBI建立了新一代测序结果子数据库________，用于存储高通量测序数据；常用公共数据库还包括EBI ENA和DDBJ DTA等。", "a": "SRA", "kp": "ch14_s0_10"}], "short": [{"id": "ch14_short_1", "modI": 0, "q": "简述Sanger测序的基本原理及其优缺点。", "a": "原理：1) 利用ddNTP终止DNA链延伸；2) 产生一系列长度不同的荧光标记片段；3) 通过毛细管电泳分离并读取碱基序列。优点：1) 读长长，可达约1000 bp；2) 准确率高，单碱基准确率可达99.999%；3) 可靠性强，适合完成精细测序和验证。缺点：1) 通量低；2) 成本高；3) 耗时长。", "kp": "ch14_s0_0"}, {"id": "ch14_short_2", "modI": 0, "q": "简述第二代测序的基本流程和核心优势。", "a": "基本流程：1) 将基因组DNA片段化；2) 两端连接接头；3) 通过乳液PCR或桥式PCR等方式生成空间固定的克隆阵列；4) 在同一平面上进行大规模并行延伸和成像检测。核心优势：1) 并行处理能力强；2) 通量高；3) 灵敏度高；4) 运行成本低。", "kp": "ch14_s0_1"}, {"id": "ch14_short_3", "modI": 0, "q": "简述RNA-seq的优势及分析重点。", "a": "优势：1) 通量高；2) 覆盖广；3) 精度高；4) 不依赖参考基因组；5) 可用于可变剪切、基因表达水平、新转录本和新基因鉴定。分析重点：1) 比对；2) 表达定量；3) 差异表达；4) 可变剪切分析。", "kp": "ch14_s0_12"}, {"id": "ch14_short_4", "modI": 0, "q": "简述ChIP-seq的原理和用途。", "a": "原理：1) 通过抗体特异性富集与蛋白质结合的DNA片段；2) 再高通量测序。用途：1) 定位转录因子结合位点；2) 定位组蛋白修饰区域；3) 研究染色质状态和表观组学。", "kp": "ch14_s0_8"}, {"id": "ch14_short_5", "modI": 0, "q": "简述单细胞测序的意义和基本流程。", "a": "意义：1) 传统测序通常使用大量混合细胞，结果反映细胞群体平均信号，可能掩盖细胞异质性；2) 单细胞测序可在单细胞水平检测基因组和转录组；3) 可揭示干细胞多能性、肿瘤异质性、免疫治疗反应和罕见细胞类型。基本流程：1) 单细胞分离；2) 裂解；3) 逆转录；4) 扩增；5) 文库构建；6) 高通量测序。", "kp": "ch14_s0_16"}], "calc": [{"id": "ch14_calc_1", "modI": 0, "q": "论述NGS在功能基因组学中的综合应用及主要挑战。", "a": "NGS可产生基因水平、转录水平和蛋白质水平等多层次数据。功能基因组学综合研究强调将DNA-seq、RNA-seq、ChIP-seq、表观组学等数据整合，进行de novo组装、CNV分析、新转录本/基因座鉴定、SNP检测、可变剪切位点分析、通路分析和调控网络重建。通过多重相关性、多重实验和网络重建，可更全面理解生物学机制。主要挑战包括数据异质性、批次效应、多组学整合算法和结果可解释性。其目标是实现精准化、全面化和动态化的生物学研究。", "steps": "1) 明确多组学数据类型；2) 整合DNA-seq、RNA-seq、ChIP-seq、表观组学等；3) 进行de novo组装、CNV分析、新转录本/基因座鉴定、SNP检测、可变剪切位点分析、通路分析和调控网络重建；4) 利用多重相关性、多重实验和网络重建理解机制；5) 关注数据异质性、批次效应、多组学整合算法和结果可解释性；6) 目标为精准化、全面化和动态化研究。", "kp": "ch14_s0_15"}, {"id": "ch14_calc_2", "modI": 0, "q": "论述宏基因组学的研究对象、意义和一般流程。", "a": "宏基因组学以某一环境中全体微生物基因组为研究对象，利用生物信息学分析微生物群落的多样性、种群结构、功能活性和相互作用。传统微生物研究依赖纯培养，但自然界约99%微生物不可培养，宏基因组学突破了这一瓶颈。最初研究常基于保守16S rRNA分析，后来发展到对环境全体微生物全部基因组测序分析。宏基因组广泛应用于海洋、土壤、肠道菌群、感染性疾病等领域。一般流程包括环境样品采集、DNA提取、文库构建、高通量测序、组装、基因预测、物种注释和功能分析。", "steps": "1) 研究对象为环境中全体微生物基因组；2) 分析多样性、种群结构、功能活性和相互作用；3) 突破纯培养限制，因约99%微生物不可培养；4) 从16S rRNA分析发展到全基因组测序分析；5) 应用于海洋、土壤、肠道菌群、感染性疾病等；6) 流程包括样品采集、DNA提取、文库构建、高通量测序、组装、基因预测、物种注释和功能分析。", "kp": "ch14_s0_16"}, {"id": "ch14_calc_3", "modI": 0, "q": "设计一个伪代码算法，用于将SOLiD测序得到的颜色编码序列解码为碱基序列。已知双碱基编码矩阵，且已知参考序列或起始碱基。分析该算法的时间复杂度。", "a": "伪代码：\n输入：颜色序列C[1..n]，起始碱基b0，双碱基编码矩阵M\n输出：碱基序列B[0..n]\nB[0] = b0\nfor i = 1 to n:\n    B[i] = M[B[i-1]][C[i]]\nreturn B\n时间复杂度：O(n)，其中n为颜色序列长度。", "steps": "1. 理解SOLiD双碱基编码：每个颜色对应前一个碱基和当前碱基的组合。\n2. 已知起始碱基后，可依次推导后续碱基。\n3. 遍历颜色序列，每次查表得到下一个碱基。\n4. 时间复杂度为线性O(n)，空间复杂度O(n)存储结果。", "kp": "ch14_s0_7"}, {"id": "ch14_calc_4", "modI": 0, "q": "设计一个RNA-seq有参考基因组分析中“先匹配再组装”策略的流程，并分析其计算复杂度主要受哪些步骤影响。", "a": "流程：\n1. 将RNA-seq reads比对到参考基因组（如使用TopHat、STAR等）。\n2. 根据比对结果将reads分配到基因组位置。\n3. 识别外显子-外显子剪接位点。\n4. 将分散的比对片段合并为转录本（如使用Cufflinks）。\n5. 进行表达量估计和差异表达分析。\n计算复杂度主要受：reads比对步骤（与reads数量和基因组大小相关）、剪接位点识别、转录本组装和表达量估计影响。", "steps": "1. 明确“先匹配再组装”的含义：先比对reads到参考基因组，再组装转录本。\n2. 列出关键步骤：比对、剪接识别、组装、定量。\n3. 分析复杂度：比对通常为O(N*M)或使用索引加速；组装和定量与转录本数量和reads覆盖度相关。\n4. 指出瓶颈通常在大规模reads比对和转录本组装。", "kp": "ch14_s0_13"}], "term": [{"id": "ch14_term_1", "modI": 0, "term": "Sanger sequencing", "def": "又称双脱氧终止法，是第一代测序的代表技术。要点：1) 利用ddNTP终止DNA链延伸；2) 产生一系列长度不同的荧光标记片段；3) 通过毛细管电泳分离并读取碱基序列；4) 读长长，可达约1000 bp；5) 单碱基准确率可达99.999%；6) 通量低、成本高、速度慢；7) 人类基因组计划主要依赖该技术。", "kp": "ch14_s0_0"}, {"id": "ch14_term_2", "modI": 0, "term": "Next-generation sequencing (NGS)", "def": "第二代测序技术，以高通量、短读长为特征。要点：1) 基本流程包括DNA片段化、连接接头、乳液PCR或桥式PCR生成克隆阵列、大规模并行延伸和成像检测；2) 核心优势是并行处理能力强、通量高、灵敏度高、运行成本低；3) 读长差异较大，约13–450 bp；4) 单次实验可产生高达100 Gb碱基数据；5) 代表平台包括Roche 454、Illumina Solexa、ABI SOLiD等；6) 多数仍依赖PCR扩增。", "kp": "ch14_s0_4"}, {"id": "ch14_term_3", "modI": 0, "term": "Third-generation sequencing", "def": "第三代测序技术，强调单分子读取。要点：1) 无需PCR扩增；2) 代表技术包括Helicos、PacBio SMRT和Oxford Nanopore；3) 核心指标包括读长、通量、是否依赖扩增、单分子能力；4) 可克服二代测序扩增偏差和短读长限制。", "kp": "ch14_s0_4"}, {"id": "ch14_term_4", "modI": 0, "term": "Pyrosequencing", "def": "Roche 454平台采用的焦磷酸合成测序原理。要点：1) DNA聚合酶催化dNTP掺入时释放焦磷酸；2) 焦磷酸与APS结合生成ATP；3) 荧光素酶催化荧光素氧化并发出荧光，报告碱基掺入事件；4) 通常采用乳液PCR，将DNA片段固定在磁珠上并在油包水小滴中扩增；5) 读长相对较长，约250 bp；6) 主要错误类型为插入缺失（Indel），尤其在同聚物区域容易产生误差。", "kp": "ch14_s0_8"}, {"id": "ch14_term_5", "modI": 0, "term": "Bridge PCR", "def": "Illumina/Solexa平台采用的固相表面扩增方法。要点：1) 在固相表面扩增DNA片段，形成克隆簇；2) 测序时使用可逆终止子标记的dNTP；3) 每轮只掺入一个碱基，通过荧光成像识别碱基类型；4) 切除荧光基团和终止基团后进入下一轮延伸；5) 读长较短，早期约36 bp，但通量极高、成本低；6) 错误类型以替换（Substitution）为主，随读长增加末端质量下降。", "kp": "ch14_s0_3"}, {"id": "ch14_term_6", "modI": 0, "term": "Two-base encoding", "def": "ABI SOLiD平台采用的双碱基编码策略。要点：1) 使用连接酶而非DNA聚合酶进行测序；2) 原始数据由四种颜色编码组成；3) 每个碱基被判读两次，可降低原始数据错误；4) 准确度可大于99.94%；5) 数据分析时需按照双碱基编码矩阵将颜色序列解码为碱基序列；6) 若已知任一位置碱基类型，即可推导整段颜色序列对应的碱基序列；7) 读长较短，约35 bp，错误类型以替换为主。", "kp": "ch14_s0_4"}, {"id": "ch14_term_7", "modI": 0, "term": "Whole-genome resequencing", "def": "对已有参考基因组的物种进行不同个体测序，并与参考基因组比对，从而发现个体或群体差异。要点：1) 可检测单核苷酸多态性（SNP）、插入缺失（InDel）和结构变异（SV）；2) 高通量测序可减少传统文库构建和亚克隆偏差；3) 数据分析依赖参考基因组和比对算法；4) 关键步骤包括读长质控、比对、变异检测、注释和群体分析。", "kp": "ch14_s0_4"}, {"id": "ch14_term_8", "modI": 0, "term": "RNA-seq", "def": "转录组测序技术。要点：1) 转录组是特定细胞或组织在某一功能状态下转录出的全部RNA，包括mRNA和非编码RNA；2) 通常先将mRNA分离并反转录为cDNA，构建片段化cDNA文库后进行高通量测序；3) RNA-seq不是直接测RNA，而是测cDNA；4) 优势包括通量高、覆盖广、精度高、不依赖参考基因组；5) 可用于可变剪切、基因表达水平、新转录本和新基因鉴定；6) 分析重点包括比对、表达定量、差异表达和可变剪切分析。", "kp": "ch14_s0_12"}, {"id": "ch14_term_9", "modI": 0, "term": "smRNA-seq", "def": "小非编码RNA测序技术。要点：1) 主要针对18–30 nt的小非编码RNA，如microRNA、tasiRNA和piRNA；2) 实验流程通常从总RNA中分离small RNA，两端加接头，反转录为cDNA，再测序；3) 分析可获得全基因组microRNA图谱；4) 用于新microRNA鉴定、差异表达、聚类和表达谱分析。", "kp": "ch14_s0_12"}, {"id": "ch14_term_10", "modI": 0, "term": "ChIP-seq", "def": "染色质免疫共沉淀测序。要点：1) 通过抗体特异性富集与蛋白质结合的DNA片段；2) 再高通量测序；3) 用于定位转录因子结合位点或组蛋白修饰区域；4) 是表观组学测序的重要方法之一。", "kp": "ch14_s0_8"}, {"id": "ch14_term_11", "modI": 0, "term": "Bisulfite sequencing", "def": "重硫酸盐测序，DNA甲基化研究的经典方法。要点：1) 未甲基化胞嘧啶转化为尿嘧啶，甲基化胞嘧啶不变；2) 常见方法包括全基因组重硫酸盐测序（MethylC-seq/BS-seq）和简化表达重硫酸盐测序（RRBS）；3) 5hmC也会抵抗重硫酸盐转化；4) 可用hMeDIP-seq、oxBS-seq或TAB-seq等方法区分5hmC。", "kp": "ch14_s0_4"}, {"id": "ch14_term_12", "modI": 0, "term": "Single-cell sequencing (SCS)", "def": "单细胞测序技术。要点：1) 传统测序通常使用大量混合细胞，结果反映细胞群体平均信号，可能掩盖细胞异质性；2) SCS可在单细胞水平检测基因组和转录组；3) 可揭示干细胞多能性、肿瘤异质性、免疫治疗反应和罕见细胞类型；4) 流程一般包括单细胞分离、裂解、逆转录、扩增、文库构建和高通量测序；5) 在癌症、免疫治疗、循环肿瘤细胞（CTC）和早期胚胎细胞研究中意义重大；6) 2016年启动的人类细胞图谱计划是重要代表。", "kp": "ch14_s0_4"}]}], "mcq": [{"id": "ch14_mcq_1", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "下列关于Sanger测序的描述，正确的是：", "o": ["A. 它属于第二代测序技术，主要特点是高通量短读长", "B. 它利用ddNTP终止DNA链延伸，准确率高但通量低", "C. 它完全不需要电泳分离即可读取碱基序列", "D. 它主要依赖桥式PCR进行信号放大"], "a": "B", "e": "Sanger测序属于第一代测序，核心是双脱氧终止法，利用ddNTP终止延伸，通过电泳分离荧光标记片段。其准确率高、读长长，但通量低、成本高。桥式PCR是Illumina二代测序的扩增方式。", "kp": "ch14_s0_0"}, {"id": "ch14_mcq_2", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "Roche 454测序平台的核心测序原理是：", "o": ["A. 桥式PCR结合可逆终止子合成测序", "B. 大规模并行焦磷酸合成测序", "C. 基于磁珠的克隆连接DNA测序", "D. 纳米孔单分子测序"], "a": "B", "e": "Roche/454采用大规模并行焦磷酸合成测序。dNTP掺入释放焦磷酸，经APS生成ATP，荧光素酶催化发光。Illumina采用桥式PCR和可逆终止子，SOLiD采用连接测序，纳米孔属于三代测序。", "kp": "ch14_s0_2"}, {"id": "ch14_mcq_3", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "Illumina Solexa测序中，桥式PCR的主要作用是：", "o": ["A. 将RNA直接转化为蛋白质", "B. 在固相表面扩增DNA片段形成克隆簇", "C. 将甲基化胞嘧啶转化为尿嘧啶", "D. 利用连接酶读取双碱基编码"], "a": "B", "e": "Illumina平台通过桥式PCR在固相表面扩增DNA片段，形成空间分离的克隆簇，再进行合成测序。RNA直接转蛋白质不是测序步骤；重硫酸盐处理用于甲基化研究；连接酶和双碱基编码属于SOLiD。", "kp": "ch14_s0_4"}, {"id": "ch14_mcq_4", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "ABI SOLiD测序中“双碱基编码”的主要优点是：", "o": ["A. 使读长达到1000 bp以上", "B. 每个碱基被判读两次，降低原始数据错误", "C. 完全不需要参考基因组即可组装", "D. 可直接测RNA而不需反转录"], "a": "B", "e": "SOLiD采用双碱基编码，每个碱基被判读两次，因此可减少原始数据错误，准确度较高。其读长较短，约35 bp，仍需建库和测序，不能直接测RNA。", "kp": "ch14_s0_5"}, {"id": "ch14_mcq_5", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "全基因组重测序（re-sequencing）通常用于：", "o": ["A. 对未知基因组物种进行从头组装", "B. 对已有参考基因组的个体进行差异分析", "C. 只检测DNA甲基化水平", "D. 只定量小非编码RNA表达"], "a": "B", "e": "全基因组重测序是对已知参考基因组的物种进行不同个体测序，通过比对发现SNP、InDel和结构变异等。从头组装适用于无参考基因组；甲基化和小RNA分析分别属于表观组学和smRNA-seq。", "kp": "ch14_s0_8"}, {"id": "ch14_mcq_6", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "RNA-seq通常测序的对象是：", "o": ["A. 直接测序原始RNA分子", "B. 反转录得到的cDNA文库", "C. 只测序蛋白质", "D. 只测序甲基化DNA"], "a": "B", "e": "RNA-seq通常先将mRNA分离并反转录为cDNA，构建cDNA文库后测序，从而推断RNA信息。它不是直接测RNA，也不是测蛋白质或甲基化DNA。", "kp": "ch14_s0_8"}, {"id": "ch14_mcq_7", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "关于ChIP-seq，下列描述正确的是：", "o": ["A. 用于研究蛋白质与DNA的结合位点", "B. 用于检测SNP和InDel", "C. 用于测定宏基因组物种多样性", "D. 用于单细胞全基因组扩增"], "a": "A", "e": "ChIP-seq即染色质免疫共沉淀测序，通过抗体富集与蛋白质结合的DNA片段，再测序定位结合位点或组蛋白修饰区域。SNP/InDel检测常由重测序完成；宏基因组和单细胞测序是其他方向。", "kp": "ch14_s0_8"}, {"id": "ch14_mcq_8", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "重硫酸盐测序（bisulfite sequencing）的原理是：", "o": ["A. 甲基化胞嘧啶转化为尿嘧啶，未甲基化胞嘧啶不变", "B. 未甲基化胞嘧啶转化为尿嘧啶，甲基化胞嘧啶不变", "C. 所有胞嘧啶都转化为腺嘌呤", "D. 所有鸟嘌呤都转化为胸腺嘧啶"], "a": "B", "e": "重硫酸盐处理使未甲基化胞嘧啶转化为尿嘧啶，而甲基化胞嘧啶保持不变，从而区分甲基化状态。5hmC也会抵抗转化，需用oxBS-seq、TAB-seq等方法进一步区分。", "kp": "ch14_s0_4"}, {"id": "ch14_mcq_9", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "在NGS差异表达分析中，单因素两组数据常用的统计方法是：", "o": ["A. t检验", "B. two-way ANOVA", "C. 隐马尔可夫模型", "D. 纳米孔测序"], "a": "A", "e": "单因素两组数据常用t检验，计算P值并筛选显著差异基因。单因素多组用one-way ANOVA，多因素用two-way ANOVA。隐马尔可夫模型属于机器学习/序列分析方法，纳米孔测序是测序技术。", "kp": "ch14_s0_10"}, {"id": "ch14_mcq_10", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "关于宏基因组学，下列描述正确的是：", "o": ["A. 只研究可纯培养的微生物", "B. 以某一环境中全体微生物基因组为研究对象", "C. 只能基于16S rRNA，不能进行全基因组测序", "D. 主要用于单细胞转录组分析"], "a": "B", "e": "宏基因组学以环境中全体微生物基因组为研究对象，可分析群落多样性、结构和功能。它突破了传统纯培养限制，最初常用16S rRNA，后来可发展到全基因组测序分析。单细胞转录组属于单细胞组学。", "kp": "ch14_s0_16"}, {"id": "ch14_mcq_11", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "在Roche 454测序中，焦磷酸测序法通过检测哪种物质的释放来间接测定DNA序列？", "o": ["A. 荧光标记的dNTP", "B. 焦磷酸", "C. ATP", "D. 荧光素"], "a": "B", "e": "Roche 454测序原理是：DNA聚合酶催化dNTP加入DNA链时释放焦磷酸，焦磷酸与APS结合生成ATP，ATP驱动荧光素酶催化荧光素氧化发光。因此直接检测的是焦磷酸释放，但最终读出的是荧光信号。", "kp": "ch14_s0_2"}, {"id": "ch14_mcq_12", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "Illumina/Solexa测序中，桥式PCR的主要作用是？", "o": ["A. 将DNA片段打断成300-800bp", "B. 在flow cell上形成密集的DNA簇", "C. 将甲基化胞嘧啶转化为尿嘧啶", "D. 连接荧光标记的8bp探针"], "a": "B", "e": "Illumina测序中，单链DNA片段与flow cell上的引物杂交，经桥式扩增形成局部密集的簇，从而提供足够的信号强度用于边合成边测序。", "kp": "ch14_s0_4"}, {"id": "ch14_mcq_13", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "SOLiD测序采用连接酶进行测序，其探针的荧光颜色由哪几个碱基决定？", "o": ["A. 第1、2位碱基", "B. 第3、4位碱基", "C. 第5、6位碱基", "D. 第7、8位碱基"], "a": "A", "e": "SOLiD探针为8bp，其中第1、2位碱基构成编码区，决定探针的荧光颜色；第3-5位为随机碱基，第6-8位为可与任何碱基配对的特殊碱基。", "kp": "ch14_s0_6"}, {"id": "ch14_mcq_14", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "在RNA-seq分析中，有参考基因组策略的两种主要流程是？", "o": ["A. 先匹配再组装、先组装再匹配", "B. 先注释再组装、先组装再注释", "C. 先聚类再匹配、先匹配再聚类", "D. 先定量再组装、先组装再定量"], "a": "A", "e": "有参考基因组RNA-seq分析策略包括“先匹配再组装”（reads先比对到参考基因组，再合并为转录本）和“先组装再匹配”（reads先组装成转录本，再比对到基因组）。", "kp": "ch14_s0_13"}, {"id": "ch14_mcq_15", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "在重硫酸盐测序（BS-seq）中，未甲基化的胞嘧啶经重硫酸盐处理后转变为？", "o": ["A. 胸腺嘧啶", "B. 尿嘧啶", "C. 腺嘌呤", "D. 鸟嘌呤"], "a": "B", "e": "重硫酸盐处理使未甲基化的胞嘧啶脱氨基转变为尿嘧啶，而甲基化的胞嘧啶保持不变。PCR扩增后尿嘧啶被读作胸腺嘧啶，从而区分甲基化状态。", "kp": "ch14_s0_9"}, {"id": "ch14_mcq_16", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "以下哪个工具主要用于NGS短序列的重新组装拼接？", "o": ["A. MOSAIK", "B. RMAP", "C. Velvet", "D. SOAP"], "a": "C", "e": "Velvet是用于短片段序列重新组装拼接的工具；MOSAIK和RMAP用于序列匹配；SOAP也用于短序列匹配到参考基因组。", "kp": "ch14_s0_11"}], "judge": [{"id": "ch14_judge_1", "modI": 0, "q": "Sanger测序是第一代测序的代表，其读长可达约1000 bp，单碱基准确率可达99.999%。", "a": "对", "e": "Sanger测序又称双脱氧终止法，读长长、准确率高，是人类基因组计划主要依赖的技术。", "kp": "ch14_s0_0"}, {"id": "ch14_judge_2", "modI": 0, "q": "第二代测序多数仍依赖PCR扩增，而三代测序强调单分子、无需扩增。", "a": "对", "e": "二代测序通过乳液PCR或桥式PCR等方式生成克隆阵列；三代测序强调单分子读取，无需PCR扩增。", "kp": "ch14_s0_1"}, {"id": "ch14_judge_3", "modI": 0, "q": "Roche 454焦磷酸测序的主要错误类型为替换（Substitution），尤其在同聚物区域容易产生误差。", "a": "错", "e": "Roche 454的主要错误类型为插入缺失（Indel），尤其在同聚物区域容易产生误差；替换为主是Illumina等平台的错误特征。", "kp": "ch14_s0_2"}, {"id": "ch14_judge_4", "modI": 0, "q": "Illumina/Solexa平台采用桥式PCR在固相表面扩增DNA片段，形成克隆簇。", "a": "对", "e": "Illumina/Solexa平台采用桥式PCR，测序时使用可逆终止子标记的dNTP，每轮只掺入一个碱基。", "kp": "ch14_s0_4"}, {"id": "ch14_judge_5", "modI": 0, "q": "ABI SOLiD平台使用DNA聚合酶进行测序，原始数据由四种颜色编码组成。", "a": "错", "e": "ABI SOLiD平台使用连接酶而非DNA聚合酶进行测序，原始数据由四种颜色编码组成。", "kp": "ch14_s0_6"}, {"id": "ch14_judge_6", "modI": 0, "q": "RNA-seq通常直接测RNA，而不是测cDNA。", "a": "错", "e": "RNA-seq通常先将mRNA分离并反转录为cDNA，构建片段化cDNA文库后进行高通量测序，因此测的是cDNA。", "kp": "ch14_s0_12"}, {"id": "ch14_judge_7", "modI": 0, "q": "重硫酸盐测序中，未甲基化胞嘧啶转化为尿嘧啶，甲基化胞嘧啶不变。", "a": "对", "e": "这是重硫酸盐测序的经典原理，用于研究DNA甲基化。", "kp": "ch14_s0_9"}, {"id": "ch14_judge_8", "modI": 0, "q": "ChIP-seq通过抗体特异性富集与蛋白质结合的DNA片段，再高通量测序，用于定位转录因子结合位点或组蛋白修饰区域。", "a": "对", "e": "ChIP-seq是表观组学测序的重要方法之一。", "kp": "ch14_s0_8"}, {"id": "ch14_judge_9", "modI": 0, "q": "单细胞测序结果反映细胞群体平均信号，可能掩盖细胞异质性。", "a": "错", "e": "传统测序通常使用大量混合细胞，结果反映细胞群体平均信号，可能掩盖细胞异质性；单细胞测序可在单细胞水平检测基因组和转录组，揭示细胞异质性。", "kp": "ch14_s0_15"}, {"id": "ch14_judge_10", "modI": 0, "q": "宏基因组学以某一环境中全体微生物基因组为研究对象，突破了传统微生物研究依赖纯培养的瓶颈。", "a": "对", "e": "自然界约99%微生物不可培养，宏基因组学利用生物信息学分析微生物群落的多样性、种群结构、功能活性和相互作用。", "kp": "ch14_s0_16"}], "fill": [{"id": "ch14_fill_1", "modI": 0, "q": "Sanger测序又称________，其核心是利用________终止DNA链延伸。", "a": "双脱氧终止法,ddNTP", "kp": "ch14_s0_0"}, {"id": "ch14_fill_2", "modI": 0, "q": "第二代测序以________、________为特征，代表平台包括Roche 454、Illumina Solexa、ABI SOLiD等。", "a": "高通量,短读长", "kp": "ch14_s0_4"}, {"id": "ch14_fill_3", "modI": 0, "q": "Roche 454焦磷酸测序中，DNA聚合酶催化dNTP掺入时释放________；焦磷酸与APS结合生成________；荧光素酶催化荧光素氧化并发出荧光。", "a": "焦磷酸,ATP", "kp": "ch14_s0_2"}, {"id": "ch14_fill_4", "modI": 0, "q": "Illumina/Solexa平台采用________在固相表面扩增DNA片段，形成克隆簇；测序时使用可逆终止子标记的dNTP，每轮只掺入________个碱基。", "a": "桥式PCR,一", "kp": "ch14_s0_4"}, {"id": "ch14_fill_5", "modI": 0, "q": "ABI SOLiD平台采用________策略，每个碱基被判读________次，因此可降低原始数据错误。", "a": "双碱基编码,两", "kp": "ch14_s0_7"}, {"id": "ch14_fill_6", "modI": 0, "q": "RNA-seq通常先将mRNA分离并反转录为________，构建片段化cDNA文库后进行高通量测序，因此RNA-seq不是直接测RNA，而是测________。", "a": "cDNA,cDNA", "kp": "ch14_s0_8"}, {"id": "ch14_fill_7", "modI": 0, "q": "重硫酸盐测序中，未甲基化胞嘧啶转化为________，甲基化胞嘧啶________。", "a": "尿嘧啶,不变", "kp": "ch14_s0_9"}, {"id": "ch14_fill_8", "modI": 0, "q": "NCBI建立了新一代测序结果子数据库________，用于存储高通量测序数据；常用公共数据库还包括EBI ENA和DDBJ DTA等。", "a": "SRA", "kp": "ch14_s0_10"}], "short": [{"id": "ch14_short_1", "modI": 0, "q": "简述Sanger测序的基本原理及其优缺点。", "a": "原理：1) 利用ddNTP终止DNA链延伸；2) 产生一系列长度不同的荧光标记片段；3) 通过毛细管电泳分离并读取碱基序列。优点：1) 读长长，可达约1000 bp；2) 准确率高，单碱基准确率可达99.999%；3) 可靠性强，适合完成精细测序和验证。缺点：1) 通量低；2) 成本高；3) 耗时长。", "kp": "ch14_s0_0"}, {"id": "ch14_short_2", "modI": 0, "q": "简述第二代测序的基本流程和核心优势。", "a": "基本流程：1) 将基因组DNA片段化；2) 两端连接接头；3) 通过乳液PCR或桥式PCR等方式生成空间固定的克隆阵列；4) 在同一平面上进行大规模并行延伸和成像检测。核心优势：1) 并行处理能力强；2) 通量高；3) 灵敏度高；4) 运行成本低。", "kp": "ch14_s0_1"}, {"id": "ch14_short_3", "modI": 0, "q": "简述RNA-seq的优势及分析重点。", "a": "优势：1) 通量高；2) 覆盖广；3) 精度高；4) 不依赖参考基因组；5) 可用于可变剪切、基因表达水平、新转录本和新基因鉴定。分析重点：1) 比对；2) 表达定量；3) 差异表达；4) 可变剪切分析。", "kp": "ch14_s0_12"}, {"id": "ch14_short_4", "modI": 0, "q": "简述ChIP-seq的原理和用途。", "a": "原理：1) 通过抗体特异性富集与蛋白质结合的DNA片段；2) 再高通量测序。用途：1) 定位转录因子结合位点；2) 定位组蛋白修饰区域；3) 研究染色质状态和表观组学。", "kp": "ch14_s0_8"}, {"id": "ch14_short_5", "modI": 0, "q": "简述单细胞测序的意义和基本流程。", "a": "意义：1) 传统测序通常使用大量混合细胞，结果反映细胞群体平均信号，可能掩盖细胞异质性；2) 单细胞测序可在单细胞水平检测基因组和转录组；3) 可揭示干细胞多能性、肿瘤异质性、免疫治疗反应和罕见细胞类型。基本流程：1) 单细胞分离；2) 裂解；3) 逆转录；4) 扩增；5) 文库构建；6) 高通量测序。", "kp": "ch14_s0_16"}], "calc": [{"id": "ch14_calc_1", "modI": 0, "q": "论述NGS在功能基因组学中的综合应用及主要挑战。", "a": "NGS可产生基因水平、转录水平和蛋白质水平等多层次数据。功能基因组学综合研究强调将DNA-seq、RNA-seq、ChIP-seq、表观组学等数据整合，进行de novo组装、CNV分析、新转录本/基因座鉴定、SNP检测、可变剪切位点分析、通路分析和调控网络重建。通过多重相关性、多重实验和网络重建，可更全面理解生物学机制。主要挑战包括数据异质性、批次效应、多组学整合算法和结果可解释性。其目标是实现精准化、全面化和动态化的生物学研究。", "steps": "1) 明确多组学数据类型；2) 整合DNA-seq、RNA-seq、ChIP-seq、表观组学等；3) 进行de novo组装、CNV分析、新转录本/基因座鉴定、SNP检测、可变剪切位点分析、通路分析和调控网络重建；4) 利用多重相关性、多重实验和网络重建理解机制；5) 关注数据异质性、批次效应、多组学整合算法和结果可解释性；6) 目标为精准化、全面化和动态化研究。", "kp": "ch14_s0_15"}, {"id": "ch14_calc_2", "modI": 0, "q": "论述宏基因组学的研究对象、意义和一般流程。", "a": "宏基因组学以某一环境中全体微生物基因组为研究对象，利用生物信息学分析微生物群落的多样性、种群结构、功能活性和相互作用。传统微生物研究依赖纯培养，但自然界约99%微生物不可培养，宏基因组学突破了这一瓶颈。最初研究常基于保守16S rRNA分析，后来发展到对环境全体微生物全部基因组测序分析。宏基因组广泛应用于海洋、土壤、肠道菌群、感染性疾病等领域。一般流程包括环境样品采集、DNA提取、文库构建、高通量测序、组装、基因预测、物种注释和功能分析。", "steps": "1) 研究对象为环境中全体微生物基因组；2) 分析多样性、种群结构、功能活性和相互作用；3) 突破纯培养限制，因约99%微生物不可培养；4) 从16S rRNA分析发展到全基因组测序分析；5) 应用于海洋、土壤、肠道菌群、感染性疾病等；6) 流程包括样品采集、DNA提取、文库构建、高通量测序、组装、基因预测、物种注释和功能分析。", "kp": "ch14_s0_16"}, {"id": "ch14_calc_3", "modI": 0, "q": "设计一个伪代码算法，用于将SOLiD测序得到的颜色编码序列解码为碱基序列。已知双碱基编码矩阵，且已知参考序列或起始碱基。分析该算法的时间复杂度。", "a": "伪代码：\n输入：颜色序列C[1..n]，起始碱基b0，双碱基编码矩阵M\n输出：碱基序列B[0..n]\nB[0] = b0\nfor i = 1 to n:\n    B[i] = M[B[i-1]][C[i]]\nreturn B\n时间复杂度：O(n)，其中n为颜色序列长度。", "steps": "1. 理解SOLiD双碱基编码：每个颜色对应前一个碱基和当前碱基的组合。\n2. 已知起始碱基后，可依次推导后续碱基。\n3. 遍历颜色序列，每次查表得到下一个碱基。\n4. 时间复杂度为线性O(n)，空间复杂度O(n)存储结果。", "kp": "ch14_s0_7"}, {"id": "ch14_calc_4", "modI": 0, "q": "设计一个RNA-seq有参考基因组分析中“先匹配再组装”策略的流程，并分析其计算复杂度主要受哪些步骤影响。", "a": "流程：\n1. 将RNA-seq reads比对到参考基因组（如使用TopHat、STAR等）。\n2. 根据比对结果将reads分配到基因组位置。\n3. 识别外显子-外显子剪接位点。\n4. 将分散的比对片段合并为转录本（如使用Cufflinks）。\n5. 进行表达量估计和差异表达分析。\n计算复杂度主要受：reads比对步骤（与reads数量和基因组大小相关）、剪接位点识别、转录本组装和表达量估计影响。", "steps": "1. 明确“先匹配再组装”的含义：先比对reads到参考基因组，再组装转录本。\n2. 列出关键步骤：比对、剪接识别、组装、定量。\n3. 分析复杂度：比对通常为O(N*M)或使用索引加速；组装和定量与转录本数量和reads覆盖度相关。\n4. 指出瓶颈通常在大规模reads比对和转录本组装。", "kp": "ch14_s0_13"}], "term": [{"id": "ch14_term_1", "modI": 0, "term": "Sanger sequencing", "def": "又称双脱氧终止法，是第一代测序的代表技术。要点：1) 利用ddNTP终止DNA链延伸；2) 产生一系列长度不同的荧光标记片段；3) 通过毛细管电泳分离并读取碱基序列；4) 读长长，可达约1000 bp；5) 单碱基准确率可达99.999%；6) 通量低、成本高、速度慢；7) 人类基因组计划主要依赖该技术。", "kp": "ch14_s0_0"}, {"id": "ch14_term_2", "modI": 0, "term": "Next-generation sequencing (NGS)", "def": "第二代测序技术，以高通量、短读长为特征。要点：1) 基本流程包括DNA片段化、连接接头、乳液PCR或桥式PCR生成克隆阵列、大规模并行延伸和成像检测；2) 核心优势是并行处理能力强、通量高、灵敏度高、运行成本低；3) 读长差异较大，约13–450 bp；4) 单次实验可产生高达100 Gb碱基数据；5) 代表平台包括Roche 454、Illumina Solexa、ABI SOLiD等；6) 多数仍依赖PCR扩增。", "kp": "ch14_s0_4"}, {"id": "ch14_term_3", "modI": 0, "term": "Third-generation sequencing", "def": "第三代测序技术，强调单分子读取。要点：1) 无需PCR扩增；2) 代表技术包括Helicos、PacBio SMRT和Oxford Nanopore；3) 核心指标包括读长、通量、是否依赖扩增、单分子能力；4) 可克服二代测序扩增偏差和短读长限制。", "kp": "ch14_s0_4"}, {"id": "ch14_term_4", "modI": 0, "term": "Pyrosequencing", "def": "Roche 454平台采用的焦磷酸合成测序原理。要点：1) DNA聚合酶催化dNTP掺入时释放焦磷酸；2) 焦磷酸与APS结合生成ATP；3) 荧光素酶催化荧光素氧化并发出荧光，报告碱基掺入事件；4) 通常采用乳液PCR，将DNA片段固定在磁珠上并在油包水小滴中扩增；5) 读长相对较长，约250 bp；6) 主要错误类型为插入缺失（Indel），尤其在同聚物区域容易产生误差。", "kp": "ch14_s0_8"}, {"id": "ch14_term_5", "modI": 0, "term": "Bridge PCR", "def": "Illumina/Solexa平台采用的固相表面扩增方法。要点：1) 在固相表面扩增DNA片段，形成克隆簇；2) 测序时使用可逆终止子标记的dNTP；3) 每轮只掺入一个碱基，通过荧光成像识别碱基类型；4) 切除荧光基团和终止基团后进入下一轮延伸；5) 读长较短，早期约36 bp，但通量极高、成本低；6) 错误类型以替换（Substitution）为主，随读长增加末端质量下降。", "kp": "ch14_s0_3"}, {"id": "ch14_term_6", "modI": 0, "term": "Two-base encoding", "def": "ABI SOLiD平台采用的双碱基编码策略。要点：1) 使用连接酶而非DNA聚合酶进行测序；2) 原始数据由四种颜色编码组成；3) 每个碱基被判读两次，可降低原始数据错误；4) 准确度可大于99.94%；5) 数据分析时需按照双碱基编码矩阵将颜色序列解码为碱基序列；6) 若已知任一位置碱基类型，即可推导整段颜色序列对应的碱基序列；7) 读长较短，约35 bp，错误类型以替换为主。", "kp": "ch14_s0_4"}, {"id": "ch14_term_7", "modI": 0, "term": "Whole-genome resequencing", "def": "对已有参考基因组的物种进行不同个体测序，并与参考基因组比对，从而发现个体或群体差异。要点：1) 可检测单核苷酸多态性（SNP）、插入缺失（InDel）和结构变异（SV）；2) 高通量测序可减少传统文库构建和亚克隆偏差；3) 数据分析依赖参考基因组和比对算法；4) 关键步骤包括读长质控、比对、变异检测、注释和群体分析。", "kp": "ch14_s0_4"}, {"id": "ch14_term_8", "modI": 0, "term": "RNA-seq", "def": "转录组测序技术。要点：1) 转录组是特定细胞或组织在某一功能状态下转录出的全部RNA，包括mRNA和非编码RNA；2) 通常先将mRNA分离并反转录为cDNA，构建片段化cDNA文库后进行高通量测序；3) RNA-seq不是直接测RNA，而是测cDNA；4) 优势包括通量高、覆盖广、精度高、不依赖参考基因组；5) 可用于可变剪切、基因表达水平、新转录本和新基因鉴定；6) 分析重点包括比对、表达定量、差异表达和可变剪切分析。", "kp": "ch14_s0_12"}, {"id": "ch14_term_9", "modI": 0, "term": "smRNA-seq", "def": "小非编码RNA测序技术。要点：1) 主要针对18–30 nt的小非编码RNA，如microRNA、tasiRNA和piRNA；2) 实验流程通常从总RNA中分离small RNA，两端加接头，反转录为cDNA，再测序；3) 分析可获得全基因组microRNA图谱；4) 用于新microRNA鉴定、差异表达、聚类和表达谱分析。", "kp": "ch14_s0_12"}, {"id": "ch14_term_10", "modI": 0, "term": "ChIP-seq", "def": "染色质免疫共沉淀测序。要点：1) 通过抗体特异性富集与蛋白质结合的DNA片段；2) 再高通量测序；3) 用于定位转录因子结合位点或组蛋白修饰区域；4) 是表观组学测序的重要方法之一。", "kp": "ch14_s0_8"}, {"id": "ch14_term_11", "modI": 0, "term": "Bisulfite sequencing", "def": "重硫酸盐测序，DNA甲基化研究的经典方法。要点：1) 未甲基化胞嘧啶转化为尿嘧啶，甲基化胞嘧啶不变；2) 常见方法包括全基因组重硫酸盐测序（MethylC-seq/BS-seq）和简化表达重硫酸盐测序（RRBS）；3) 5hmC也会抵抗重硫酸盐转化；4) 可用hMeDIP-seq、oxBS-seq或TAB-seq等方法区分5hmC。", "kp": "ch14_s0_4"}, {"id": "ch14_term_12", "modI": 0, "term": "Single-cell sequencing (SCS)", "def": "单细胞测序技术。要点：1) 传统测序通常使用大量混合细胞，结果反映细胞群体平均信号，可能掩盖细胞异质性；2) SCS可在单细胞水平检测基因组和转录组；3) 可揭示干细胞多能性、肿瘤异质性、免疫治疗反应和罕见细胞类型；4) 流程一般包括单细胞分离、裂解、逆转录、扩增、文库构建和高通量测序；5) 在癌症、免疫治疗、循环肿瘤细胞（CTC）和早期胚胎细胞研究中意义重大；6) 2016年启动的人类细胞图谱计划是重要代表。", "kp": "ch14_s0_4"}], "preview": {"main": "本章围绕新一代测序技术展开，先回顾Sanger测序并介绍第二代和第三代测序平台及其原理，重点包括454、Illumina/Solexa和SOLiD；随后讲解第二代测序在RNA-seq、小RNA、lncRNA、ChIP-seq、DNA甲基化、单细胞测序和宏基因组学中的应用；最后讨论生物信息学分析流程、常用工具、新技术发展趋势及数据挑战。", "questions": ["第二代测序与第三代测序在原理、读长、通量和成本上有哪些主要区别？", "Roche 454、Illumina/Solexa和SOLiD三种平台的测序原理和流程分别是什么？", "RNA-seq在无参考基因组和有参考基因组时，生物信息学分析策略有何不同？", "ChIP-seq、BS-seq和RRBS分别用于研究哪些表观遗传问题？其基本流程是什么？", "单细胞测序、宏基因组学和Hi-C技术之间如何相互补充？它们面临哪些生物信息学挑战？"]}, "appcards": [{"front": "应用/分析型问题：某实验室希望从一份环境宏基因组样本中同时获得微生物群落组成和其中优势菌的完整基因组，并尽可能减少组装碎片化。请结合本章内容，设计一条合理的技术路线并说明理由。", "back": "要点式参考答案：1）先对宏基因组样本进行二代高通量短读长测序（如Illumina），用于群落组成分析、物种注释和丰度估计；2）对同一或类似样本进行三代单分子长读长测序，利用长读长跨越重复区域，提高宏基因组组装连续性；3）可结合Hi-C技术，通过染色质构象信息将来自同一微生物的contig聚类和分箱，辅助不同微生物基因组的组装；4）若目标微生物丰度低，可考虑单细胞测序或单细胞分选后测序，避免环境DNA背景干扰；5）最后结合生物信息学工具进行序列匹配、组装、注释和比较分析。", "points": "踩分点：二代短读长用于群落组成/丰度；三代长读长提高组装连续性；Hi-C辅助宏基因组分箱组装；单细胞测序辅助低丰度或难培养微生物；生物信息学组装与注释流程。", "mod": 0, "modName": "第十四章 新一代测序技术及其应用", "level": "掌握", "src": "生成"}, {"front": "应用/分析型问题：在RNA-seq数据分析中，如果研究对象没有参考基因组，应如何开展转录组分析？若有参考基因组，又有哪些常见策略？请比较其分析思路。", "back": "要点式参考答案：无参考基因组时：1）先进行测序数据产量统计、去冗余、数据成分与质量评估；2）用Cufflinks等软件重建转录本；3）计算Contig/Scaffold和Unigene长度分布；4）进行功能注释、GO分类、代谢通路分析；5）获得Unigene表达量并进行差异表达、聚类等分析。有参考基因组时：1）可采用“先匹配再组装”，即将reads先比对到参考基因组，再合并分散片段为转录本；2）也可采用“先组装再匹配”，即先将reads组装成转录本，再比对到基因组；3）进一步分析可变剪接、新转录本、基因融合、SNP/InDel等。", "points": "踩分点：无参考基因组需de novo组装与注释；有参考基因组可先比对或先组装；Cufflinks等工具；质量评估、功能注释、GO/通路、差异表达；可变剪接、新转录本、基因融合等。", "mod": 0, "modName": "第十四章 新一代测序技术及其应用", "level": "掌握", "src": "生成"}, {"front": "应用/分析型问题：某研究团队想同时分析肿瘤样本中的DNA甲基化状态、组蛋白修饰区域和基因表达变化。请基于第二代测序技术，提出可组合使用的测序策略，并说明各策略的主要用途。", "back": "要点式参考答案：1）DNA甲基化分析：可采用全基因组重硫酸盐测序（MethylC-seq/BS-seq）或简化表达重硫酸盐测序（RRBS），检测未甲基化C转化为U、甲基化C不变的位点；2）组蛋白修饰和转录因子结合分析：可采用ChIP-seq，通过抗体免疫沉淀结合DNA，经超声打断、接头连接、PCR扩增和高通量测序，统计Unique mapped reads在重复区域、基因区间、基因上的分布和覆盖深度；3）基因表达分析：可采用RNA-seq，分析转录本表达、差异表达、可变剪接、新转录本和基因融合等；4）整合分析：将甲基化、ChIP-seq和RNA-seq数据联合，研究表观遗传修饰对基因表达的调控。", "points": "踩分点：BS-seq/RRBS用于DNA甲基化；ChIP-seq用于组蛋白修饰/蛋白-DNA结合；RNA-seq用于表达分析；多组学整合；重硫酸盐处理原理；ChIP-seq流程关键步骤。", "mod": 0, "modName": "第十四章 新一代测序技术及其应用", "level": "掌握", "src": "生成"}, {"front": "应用/分析型问题：单细胞测序、宏基因组学和Hi-C技术之间有何联系？它们分别能解决哪些传统测序难以解决的问题？", "back": "要点式参考答案：1）单细胞测序可研究细胞异质性，如癌症内异质性、肿瘤循环细胞（CTC）、早期胚胎细胞等数量不足的细胞，并提升基因表达测量精度和罕见非编码RNA发现能力；2）宏基因组学可研究人体共生微生物群落结构、分子过程与健康关系，如人类微生物组计划（HMP）分析鼻腔、口腔、皮肤、胃肠道和泌尿生殖道样本；3）Hi-C技术通过染色质交联、酶切、生物素标记、连接、纯化和测序，研究三维基因组结构，并可辅助宏基因组中不同微生物基因组的组装；4）第三代单分子测序可免去单细胞测序中的扩增步骤，提高精确性；单细胞测序可辅助宏基因组测序发现新细菌；Hi-C可帮助宏基因组组装。", "points": "踩分点：单细胞测序解决细胞异质性和微量细胞问题；宏基因组研究微生物群落与健康；Hi-C研究三维基因组并辅助宏基因组组装；三代测序与单细胞测序互补；新技术间相互促进。", "mod": 0, "modName": "第十四章 新一代测序技术及其应用", "level": "掌握", "src": "生成"}]};